import{_ as n,o as s,c as a,f as t,a as o}from"./app-v4ODCOL5.js";const e={},p=o(`<h2 id="第-3-章-异步编程与事件循环" tabindex="-1"><a class="header-anchor" href="#第-3-章-异步编程与事件循环" aria-hidden="true">#</a> 第 3 章 异步编程与事件循环</h2><h3 id="q1-为什么-javascript-需要异步-全部同步执行不行吗" tabindex="-1"><a class="header-anchor" href="#q1-为什么-javascript-需要异步-全部同步执行不行吗" aria-hidden="true">#</a> Q1 为什么 JavaScript 需要异步？全部同步执行不行吗？</h3><p><strong>考察点</strong>：考你是否理解单线程语言阻塞的代价，以及异步真正要解决的问题。能说出&quot;阻塞渲染和响应&quot;就算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：因为 JS 主线程既跑代码又负责渲染，同步等待会把页面卡死；异步的本质是把&quot;等待&quot;交出去、把&quot;结果处理&quot;留下来当回调。</p></blockquote><ol><li>主线程职责重：脚本执行、样式计算、布局、绘制、事件响应都在主线程。一次同步耗时操作（同步 XHR、几百万次循环、大数组排序）期间，页面既不渲染也不响应点击。</li><li>等待型任务占多数：网络请求、定时器、文件读取、用户输入，耗时都在&quot;等&quot;而不在&quot;算&quot;。同步等待等于让 CPU 空转，异步则让主线程先去干别的。</li><li>异步的落地机制是&quot;回调 + 事件循环（Event Loop）&quot;：任务交给浏览器背后的机制（网络栈、定时器调度）执行，完成后把回调排进队列，主线程空下来再取出来运行。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 输出：1 3 2</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 Web Worker 算不算异步？答：不算同一层面的东西。Worker 是真的开了后台线程跑 JS，解决的是&quot;计算密集&quot;，异步解决的是&quot;等待&quot;。</li><li>陷阱：说&quot;JS 单线程所以不能并发&quot;。能并发的从来不是 JS 代码本身，而是浏览器替我们并行等待的 IO。</li></ul><h3 id="q2-都说-js-是单线程-那浏览器的多进程多线程怎么解释" tabindex="-1"><a class="header-anchor" href="#q2-都说-js-是单线程-那浏览器的多进程多线程怎么解释" aria-hidden="true">#</a> Q2 都说 JS 是单线程，那浏览器的多进程多线程怎么解释？</h3><p><strong>考察点</strong>：考你能不能把&quot;单线程&quot;和&quot;浏览器架构&quot;分开讲。这是最容易被追问穿的一题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：&quot;单线程&quot;指的是<strong>渲染进程主线程执行 JS 这件事</strong>，浏览器整体是多进程 + 多线程架构，IO 并行由浏览器完成，与 JS 代码并发无关。</p></blockquote><ol><li>多进程（以 Chromium 为例）：浏览器主进程（Browser，管窗口、地址栏、网络服务）、渲染进程（Renderer，跑 HTML/CSS/JS）、GPU 进程（合成与绘制）、插件/工具进程。出于安全与稳定，一般每个标签页一个渲染进程，开启站点隔离后还会按站点再拆。</li><li>渲染进程内多线程：主线程（JS 引擎 + DOM + 样式布局）、合成线程（Compositor，独立滚动与合成）、光栅线程（Raster）、以及工作线程（Worker）。主线程被 JS 占住时，合成线程仍能让&quot;已有图层&quot;的滚动和 transform 动画继续跑。</li><li>事件循环属于渲染进程的主线程。定时器到点、网络返回、用户点击，都会变成任务被投递回主线程的任务队列（Task Queue），排队等主线程空闲。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>transform</code> 动画比 <code>left</code> 动画流畅？答：<code>transform</code> 由合成线程处理，不占主线程；改 <code>left</code> 要走主线程的布局与绘制，主线程一忙就掉帧。</li><li>陷阱：把&quot;主线程&quot;当成&quot;整个浏览器只有一个线程&quot;。也别说&quot;JS 引擎是单线程，所以浏览器也是单线程&quot;。</li><li>陷阱：说 setTimeout 由&quot;另一个线程&quot;执行。准确说法是：计时由浏览器托管，到点后把回调交回主线程执行。</li></ul><h3 id="q3-完整讲一下事件循环-event-loop-的模型" tabindex="-1"><a class="header-anchor" href="#q3-完整讲一下事件循环-event-loop-的模型" aria-hidden="true">#</a> Q3 完整讲一下事件循环（Event Loop）的模型？</h3><p><strong>考察点</strong>：考结构是否完整。能按&quot;调用栈 → 微任务清空 → 渲染 → 下一个宏任务&quot;讲清楚，并把调用栈和两类队列都说到，才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：事件循环就是主线程反复执行&quot;取出一个宏任务执行到调用栈（Call Stack）清空 → 清空整个微任务（Microtask）队列 → 视情况执行渲染步骤 → 再取下一个宏任务&quot;。</p></blockquote><ol><li><strong>调用栈</strong>：当前正在执行的同步代码。栈不空，任何队列里的东西都不能执行。这是&quot;JS 单线程&quot;的直接体现。</li><li><strong>宏任务队列（Task Queue）</strong>：存放一个个宏任务。每轮循环只取<strong>一个</strong>宏任务执行。</li><li><strong>微任务队列（Microtask Queue）</strong>：当前宏任务结束后、渲染之前，必须把微任务队列<strong>彻底清空</strong>，包括清空过程中新产生的微任务。</li><li><strong>渲染步骤（Update the Rendering）</strong>：不是每轮循环都渲染，浏览器按屏幕刷新率（常见 60Hz，约 16.7ms）决定是否渲染。要渲染时依次执行 <code>requestAnimationFrame</code> 回调、样式计算、布局、绘制、合成。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 一轮 tick 的顺序示意</span>
<span class="token comment">// 1. 取出一个宏任务执行 -&gt; 2. 栈空 -&gt; 3. 清空微任务 -&gt; 4. 需要渲染则渲染 -&gt; 5. 下一个宏任务</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;同步&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;微任务&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">requestAnimationFrame</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;渲染前&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;下一个宏任务&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 同步 -&gt; 微任务 -&gt; (渲染帧) 渲染前 -&gt; 下一个宏任务</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：渲染一定每轮都发生吗？答：不一定。主线程被连续同步任务占满时，浏览器可能跳过若干帧，这就是掉帧。</li><li>陷阱：说&quot;每执行一个宏任务就渲染一次&quot;。渲染是低频的、由刷新率驱动的，不是每轮都来。</li><li>陷阱：把 <code>requestAnimationFrame</code> 简单归成宏任务。它属于渲染步骤，比普通宏任务更早，见 Q10。</li></ul><h3 id="q4-宏任务和微任务分别有哪些-执行顺序是什么" tabindex="-1"><a class="header-anchor" href="#q4-宏任务和微任务分别有哪些-执行顺序是什么" aria-hidden="true">#</a> Q4 宏任务和微任务分别有哪些？执行顺序是什么？</h3><p><strong>考察点</strong>：分类要背准，顺序要能一句话说清。这是纯记忆题，答错说明基础不牢。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：宏任务之间必须清空微任务队列才能轮下一个；同步代码永远最先，微任务永远早于下一个宏任务。</p></blockquote><ol><li>常见宏任务：整段 <code>script</code>、<code>setTimeout</code>、<code>setInterval</code>、<code>setImmediate</code>（Node）、<code>MessageChannel</code>、IO 回调、UI 事件回调。</li><li>常见微任务：<code>Promise.then/catch/finally</code>、<code>queueMicrotask</code>、<code>MutationObserver</code>、<code>await</code> 之后的续体代码、Node 的 <code>process.nextTick</code>（优先级高于 Promise 微任务）。</li><li>顺序口诀：<strong>同步代码 → 清空微任务 → 取下一个宏任务 → 清空微任务 → ……</strong>。微任务插队的能力来自&quot;每个宏任务结束后立即清空&quot;，所以它总是比排在后面的宏任务先跑。</li><li><code>requestAnimationFrame</code> 单独记：它不在宏任务队列里，属于渲染前的回调。</li></ol><table><thead><tr><th>类别</th><th>典型成员</th><th>执行时机</th></tr></thead><tbody><tr><td>同步代码</td><td>当前 script</td><td>立即</td></tr><tr><td>微任务</td><td><code>Promise.then</code>、<code>queueMicrotask</code>、<code>await</code> 续体</td><td>每个宏任务后清空</td></tr><tr><td>渲染回调</td><td><code>requestAnimationFrame</code></td><td>渲染步骤开始时</td></tr><tr><td>宏任务</td><td><code>setTimeout</code>、事件回调、IO</td><td>每轮取一个</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：微任务里再产生微任务怎么办？答：继续入队，本轮内一并清空，直到队列为空。</li><li>陷阱：把 <code>requestAnimationFrame</code> 说成微任务或普通宏任务。也别说 <code>setTimeout</code> 比 <code>Promise.then</code> 快——即使延迟写 0，它也得等下一轮。</li></ul><h3 id="q5-一个完整的-tick-里-同步代码、微任务、渲染、下一个宏任务是怎么排的" tabindex="-1"><a class="header-anchor" href="#q5-一个完整的-tick-里-同步代码、微任务、渲染、下一个宏任务是怎么排的" aria-hidden="true">#</a> Q5 一个完整的 tick 里，同步代码、微任务、渲染、下一个宏任务是怎么排的？</h3><p><strong>考察点</strong>：考你把 Q3 的模型落到具体时序上，能讲出&quot;渲染插在微任务之后、下一个宏任务之前&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：同步代码跑完 → 微任务全部清空 → 需要的话做一次渲染（含 rAF）→ 再取下一个宏任务，如此循环。</p></blockquote><ol><li>第一轮循环的宏任务其实就是整段 <code>script</code>，所以&quot;同步代码最先&quot;是必然的。</li><li>栈空之后进入微任务检查点（Microtask Checkpoint），把队列清空。此时页面还没更新，DOM 修改虽然已经写进内存，但用户看不到。</li><li>清空后才进入渲染判断：如果距上一帧够久或者有脏标记，就执行渲染步骤。因此&quot;微任务里改 DOM&quot;在同一帧内就完成了，不会先渲染一版旧数据。</li><li>渲染完成后才取下一个宏任务，所以 <code>setTimeout(fn, 16)</code> 实际感知到的延迟通常 ≥ 16ms 而不是恰好 16ms。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>document<span class="token punctuation">.</span>body<span class="token punctuation">.</span>textContent <span class="token operator">=</span> <span class="token string">&#39;A&#39;</span><span class="token punctuation">;</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> document<span class="token punctuation">.</span>body<span class="token punctuation">.</span>textContent <span class="token operator">=</span> <span class="token string">&#39;B&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 用户只会看到 B，A 永远不会被画出来</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>nextTick</code> 为什么能拿到最新 DOM？答：Vue 的 <code>nextTick</code> 把回调放进微任务，微任务在渲染前执行，此时 DOM 已更新但未绘制，读到的是最新结构。</li><li>陷阱：说&quot;DOM 改一次就重绘一次&quot;。同一轮内的多次修改会被合并，只在渲染步骤统一处理。</li></ul><h3 id="q6-settimeout-fn-0-是立即执行吗-4ms-又是怎么回事" tabindex="-1"><a class="header-anchor" href="#q6-settimeout-fn-0-是立即执行吗-4ms-又是怎么回事" aria-hidden="true">#</a> Q6 setTimeout(fn, 0) 是立即执行吗？4ms 又是怎么回事？</h3><p><strong>考察点</strong>：考定时器语义与嵌套钳制。答出&quot;不早于&quot;和&quot;嵌套超过 5 层按 4ms&quot;就过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>setTimeout(fn, 0)</code> 的语义是&quot;至少 0ms 后尽快&quot;，但要等当前宏任务和全部微任务结束、且轮到它；嵌套层级大于 5 层时，规范强制按 4ms 处理。</p></blockquote><ol><li>延迟是下界不是上界：定时器只承诺&quot;不早于&quot;，不承诺&quot;恰好&quot;。前面有长任务或微任务队列很长时，实际延迟会被无限拉长。</li><li>4ms 钳制：HTML 规范规定，当定时器的嵌套层级（nesting level）大于 5、且设定延迟小于 4ms 时，按 4ms 处理。也就是说连续用 <code>setTimeout</code> 自我嵌套到第 6 层开始，最快只能 4ms 一次。</li><li>实际下限还受浏览器与系统时钟精度影响，通常不会真正小于 1ms；页面进入后台还会被进一步节流（见 Q44）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> start <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token function">loop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  n<span class="token operator">++</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">===</span> <span class="token number">8</span><span class="token punctuation">)</span> <span class="token keyword">return</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;8 层嵌套耗时约&#39;</span><span class="token punctuation">,</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> start<span class="token punctuation">,</span> <span class="token string">&#39;ms&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 明显大于 8ms</span>
  <span class="token function">setTimeout</span><span class="token punctuation">(</span>loop<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那要精确 0ms 延迟怎么办？答：用微任务，<code>queueMicrotask</code> 或 <code>Promise.resolve().then</code>，它们在同一轮就执行完，不经过定时器队列。</li><li>陷阱：答&quot;0ms 表示马上执行&quot;。规范里除嵌套钳制外没有固定最小值，但&quot;排队等待&quot;这件事本身就意味着不可能是立即。</li><li>陷阱：以为 <code>setTimeout(fn, 0)</code> 和 <code>setTimeout(fn)</code> 有语义差异。省略延迟等价于 0，都走同一套钳制规则。</li></ul><h3 id="q7-settimeout-和-setinterval-会漂移吗-漂移从哪来" tabindex="-1"><a class="header-anchor" href="#q7-settimeout-和-setinterval-会漂移吗-漂移从哪来" aria-hidden="true">#</a> Q7 setTimeout 和 setInterval 会漂移吗？漂移从哪来？</h3><p><strong>考察点</strong>：考你是否知道定时器不精确的根本原因，而不是背&quot;会漂移&quot;三个字。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：会漂移。定时器只保证不早于设定时间，回调自身耗时、事件循环被占用、浏览器节流，都会让实际触发点越来越晚。</p></blockquote><ol><li>漂移的三个来源：回调自身的执行耗时；回调前面排着的其他任务（长任务、长微任务队列）；浏览器对后台页面与嵌套定时器的节流。</li><li><code>setInterval</code> 的问题更明显：它每隔 interval 触发，但每次触发都要重新排队等主线程空闲。回调耗时超过间隔时，实际间隔等于&quot;回调耗时 + 排队时间&quot;，时间点相对墙钟越走越偏。</li><li>关键定时不要依赖 <code>setInterval</code> 的累计次数，改用&quot;绝对时间点 + 递归 setTimeout&quot;来自我校正。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> start <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token function">tick</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  count<span class="token operator">++</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> deadline <span class="token operator">=</span> start <span class="token operator">+</span> count <span class="token operator">*</span> <span class="token number">1000</span><span class="token punctuation">;</span>      <span class="token comment">// 目标绝对时间点</span>
  <span class="token function">setTimeout</span><span class="token punctuation">(</span>tick<span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> deadline <span class="token operator">-</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 每次重新算剩余时间</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>setInterval</code> 会不会补跑漏掉的次数？答：不会累积补跑。错过就错过了，表现是间隔被拉长，而不是后面连续触发一长串。</li><li>陷阱：用 <code>setInterval</code> 做倒计时并用计数器递减。主线程一卡就少跳一秒，正确做法是每帧拿 <code>Date.now()</code> 和截止时间相减。</li></ul><h3 id="q8-为什么推荐用递归-settimeout-代替-setinterval" tabindex="-1"><a class="header-anchor" href="#q8-为什么推荐用递归-settimeout-代替-setinterval" aria-hidden="true">#</a> Q8 为什么推荐用递归 setTimeout 代替 setInterval？</h3><p><strong>考察点</strong>：考取舍能力。要说出两者在执行模型上的差别，而不是&quot;网上都这么说&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：递归 <code>setTimeout</code> 保证上一次回调执行完才排下一次，天然消除堆积与漂移，还能动态调间隔、方便取消与异常处理。</p></blockquote><ol><li>不会堆积：<code>setInterval</code> 的下一拍与上一拍回调是否结束无关；如果回调里有 <code>await</code> 网络请求，可能出现多次回调重叠执行。递归 <code>setTimeout</code> 天然串行。</li><li>可自我校正：每次用绝对时间点算剩余延迟，长时间运行也不会累计漂移（见 Q7 代码）。</li><li>可动态调整与安全退出：根据业务状态改变下一次间隔（轮询退避），或在出错时不再续排，避免&quot;停不下来的定时器&quot;。</li></ol><table><thead><tr><th>维度</th><th>setInterval</th><th>递归 setTimeout</th></tr></thead><tbody><tr><td>回调重叠</td><td>可能</td><td>不会</td></tr><tr><td>漂移</td><td>会累积</td><td>可用绝对时间校正</td></tr><tr><td>动态间隔</td><td>需先 clear 再重设</td><td>每轮自由决定</td></tr><tr><td>出错停止</td><td>需手动 clear</td><td>直接不续排</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>setInterval</code> 还有使用场景吗？答：有，纯装饰性、无依赖、允许重叠的轻量任务，或者用 <code>setInterval</code> 只做&quot;检查时间是否到点&quot;的哨兵。</li><li>陷阱：递归写法里忘了在异常时停止，导致定时器永久续排。要在 <code>catch</code> 里决定是否继续。</li><li>陷阱：递归 <code>setTimeout</code> 的间隔是&quot;回调结束后再等 N 毫秒&quot;，所以实际周期 = 回调耗时 + N。若要求固定周期，必须用绝对时间点算差值。</li></ul><h3 id="q9-做动画为什么用-requestanimationframe-而不是定时器" tabindex="-1"><a class="header-anchor" href="#q9-做动画为什么用-requestanimationframe-而不是定时器" aria-hidden="true">#</a> Q9 做动画为什么用 requestAnimationFrame 而不是定时器？</h3><p><strong>考察点</strong>：考你是否理解帧同步。答出&quot;与刷新率对齐、后台自动暂停、不丢帧&quot;即可。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>requestAnimationFrame</code> 由浏览器按屏幕刷新节奏统一调度，回调在渲染前执行，天然不丢帧、不空转，后台还会自动暂停。</p></blockquote><ol><li>帧同步：rAF 回调在当前帧的渲染步骤中执行，刷新率 60Hz 就约 16.7ms 一次，120Hz 就约 8.3ms 一次。它不需要你猜屏幕多久刷一次。</li><li>不空转：屏幕不刷新（后台标签页、页面不可见）时 rAF 不执行，省电。<code>setInterval(fn, 16)</code> 在后台仍会跑，然后被浏览器节流得七零八落。</li><li>不撕裂：因为回调紧挨着渲染，写入的样式会在同一帧生效，视觉上更连续；定时器则可能在两帧之间插入或错过。</li><li>定时器做动画的典型症状是忽快忽慢、跳帧——因为它和屏幕刷新节奏无关，还会和渲染抢主线程。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：rAF 能保证一定 60fps 吗？答：不能。它只保证&quot;要渲染时叫我&quot;，主线程被长任务占住照样掉帧，需要用 <code>performance.now()</code> 自己算时间差做插值。</li><li>陷阱：说 rAF 精度比定时器高所以更快。rAF 的上限就是刷新率，它比 <code>setTimeout(fn, 0)</code> 慢得多，只是&quot;更对&quot;。</li><li>陷阱：以为 rAF 会自动取消。必须用 <code>cancelAnimationFrame(id)</code> 手动停，否则递归调用会一直排。</li></ul><h3 id="q10-requestanimationframe-在事件循环里到底什么时候执行" tabindex="-1"><a class="header-anchor" href="#q10-requestanimationframe-在事件循环里到底什么时候执行" aria-hidden="true">#</a> Q10 requestAnimationFrame 在事件循环里到底什么时候执行？</h3><p><strong>考察点</strong>：考你对渲染步骤的精确位置认知。这是区分&quot;背过资料&quot;和&quot;真理解&quot;的一题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：rAF 回调位于&quot;微任务清空之后、样式计算与布局之前&quot;的渲染步骤开头，不属于宏任务队列。</p></blockquote><ol><li>精确顺序：当前宏任务执行完 → 清空微任务 → 浏览器判断该渲染了 → <strong>执行 rAF 回调</strong> → 样式计算（Recalc Style）→ 布局（Layout）→ 绘制（Paint）→ 合成（Composite）。</li><li>因此 rAF 里读布局信息（<code>offsetHeight</code>、<code>getBoundingClientRect</code>）拿到的是&quot;上一帧已算好的值&quot;；在这里写样式也不会立刻触发布局，会和后续的样式计算合并。</li><li>一帧内 rAF 回调按注册顺序执行；在 rAF 里再调用 rAF 会排到<strong>下一帧</strong>，不会在本帧重复执行。</li><li>常见误区是把它归入宏任务队列。它和 <code>setTimeout</code> 不在一个队列，所以&quot;先 rAF 还是先 setTimeout(fn, 0)&quot;取决于定时器是否已到期，不能一概而论。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;timeout&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">requestAnimationFrame</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;raf&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 一段耗时很长的同步代码后：通常是 raf 先，因为定时器要等下一个宏任务，rAF 在本帧渲染前</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：rAF 里能不能改 DOM？答：能，而且是最佳位置。改完紧接样式计算和布局，同一帧生效，避免强制同步布局。</li><li>陷阱：在 rAF 里先写样式再读 <code>offsetHeight</code>，这会强制浏览器立刻做一次同步布局（强制重排），是性能大坑。读写要分开。</li></ul><h3 id="q11-requestidlecallback-是干什么的-什么时候用" tabindex="-1"><a class="header-anchor" href="#q11-requestidlecallback-是干什么的-什么时候用" aria-hidden="true">#</a> Q11 requestIdleCallback 是干什么的？什么时候用？</h3><p><strong>考察点</strong>：考你是否知道浏览器提供的&quot;低优先级任务&quot;接口及其限制。知道它不稳、兼容性差就是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>requestIdleCallback</code> 让你在浏览器每帧的空闲时段执行低优先级任务，是&quot;能拖就拖&quot;的任务调度方案。</p></blockquote><ol><li>回调收到一个 <code>deadline</code> 对象：<code>timeRemaining()</code> 返回本帧剩余空闲毫秒数（上限通常 50ms），<code>didTimeout</code> 表示是否因为超时被强制执行。</li><li>没有空闲时段就一直不执行。用 <code>{ timeout: 2000 }</code> 可以保证最晚 2 秒内被执行一次，此时 <code>didTimeout</code> 为 <code>true</code>。</li><li>适合：日志上报批量发送、预计算、预渲染不重要内容、大数据分片处理。不适合：动画、必须及时响应的交互。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token function">requestIdleCallback</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token function">work</span><span class="token punctuation">(</span><span class="token parameter">deadline</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>deadline<span class="token punctuation">.</span><span class="token function">timeRemaining</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token number">1</span> <span class="token operator">&amp;&amp;</span> queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">process</span><span class="token punctuation">(</span>queue<span class="token punctuation">.</span><span class="token function">shift</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 只干到快没时间</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token function">requestIdleCallback</span><span class="token punctuation">(</span>work<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 剩下的下一帧继续</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">timeout</span><span class="token operator">:</span> <span class="token number">2000</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么实际业务里用得少？答：Chromium 与 Firefox 支持，Safari 长期未实现，需要落到 <code>setTimeout</code> 或 <code>MessageChannel</code> 做降级；而且空闲时段不可预期，任务可能被饿很久。</li><li>陷阱：把它当&quot;低延迟&quot;接口用。它的定位恰恰是&quot;可以被推迟&quot;，React 早期调度器用过它，后来因触发不稳定与 50ms 限制改用了 MessageChannel。</li></ul><h3 id="q12-输出顺序题-基础-这四行打印顺序是什么" tabindex="-1"><a class="header-anchor" href="#q12-输出顺序题-基础-这四行打印顺序是什么" aria-hidden="true">#</a> Q12 输出顺序题（基础）：这四行打印顺序是什么？</h3><p><strong>考察点</strong>：最基础的宏微任务顺序题。答错说明事件循环还没入门。</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;script start&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;setTimeout&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;promise&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;script end&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>script start → script end → promise → setTimeout</code>，同步代码最先，微任务早于下一个宏任务。</p></blockquote><ol><li><code>console.log(&#39;script start&#39;)</code> 是同步代码，立刻打印。</li><li><code>setTimeout</code> 把回调交给定时器，到期后作为<strong>宏任务</strong>进入任务队列，本轮不执行。</li><li><code>Promise.resolve().then</code> 把回调作为<strong>微任务</strong>入队，本轮不立即执行。</li><li><code>console.log(&#39;script end&#39;)</code> 同步打印。至此整个 <code>script</code> 这个宏任务结束，进入微任务检查点，打印 <code>promise</code>；微任务清空后才取下一个宏任务，打印 <code>setTimeout</code>。</li></ol><p>逐行分析：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>同步阶段   : script start, script end
微任务队列 : [promise 回调]   &lt;- 栈空后清空
宏任务队列 : [setTimeout 回调] &lt;- 微任务清空后才取
结果       : script start, script end, promise, setTimeout
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：把 <code>setTimeout</code> 的 0 改成 1 会变吗？答：不变。只要定时器还没到期，它就得等下一个宏任务，而微任务在本轮清空。</li><li>陷阱：答成 <code>script start → promise → script end → setTimeout</code>。<code>then</code> 的回调不会插到同步代码中间。</li></ul><h3 id="q13-输出顺序题-进阶-async-await-和-promise-then-混在一起怎么排" tabindex="-1"><a class="header-anchor" href="#q13-输出顺序题-进阶-async-await-和-promise-then-混在一起怎么排" aria-hidden="true">#</a> Q13 输出顺序题（进阶）：async/await 和 Promise.then 混在一起怎么排？</h3><p><strong>考察点</strong>：考 <code>await</code> 之后的代码到底排在哪。核心是&quot;<code>await</code> 会让出主线程，后续代码进微任务队列&quot;。</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">async1</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;async1 start&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">await</span> <span class="token function">async2</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;async1 end&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">async2</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;async2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>

console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;script start&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;setTimeout&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">async1</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;promise1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;promise2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;script end&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>script start → async1 start → async2 → promise1 → script end → async1 end → promise2 → setTimeout</code>。</p></blockquote><ol><li><code>async1()</code> 同步执行到 <code>await</code> 之前：先打印 <code>async1 start</code>。<code>async2()</code> 是普通调用，同步打印 <code>async2</code> 并返回一个已完成的 Promise。</li><li><code>await</code> 会把 <code>async1</code> 后续代码包装成续体排进<strong>微任务队列</strong>，主线程继续往下走，所以 <code>promise1</code> 和 <code>script end</code> 先打印。</li><li>两个微任务按入队顺序执行：<code>async1</code> 的续体先于 <code>then</code> 回调，所以是 <code>async1 end</code> 再 <code>promise2</code>。</li><li><code>setTimeout</code> 是宏任务，排在所有微任务之后。</li></ol><p>逐行时序：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>同步   : script start → async1 start → async2 → promise1 → script end
微任务 : [async1 续体, promise2 回调] -&gt; async1 end, promise2
宏任务 : setTimeout
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>async1 end</code> 在 <code>promise2</code> 前面？答：<code>await</code> 在同步阶段就完成了入队，而 <code>promise2</code> 的 <code>then</code> 是在 <code>resolve()</code> 之后才注册入队，入队晚。</li><li>陷阱：老版本引擎（Chrome 73 / Node 12 之前）的 <code>await</code> 需要 3 个微任务 tick，输出会变成 <code>promise2</code> 在前。现在只需 1 个 tick，面试按新规范答，并主动说明这个历史差异会很加分。</li><li>陷阱：说 <code>await async2()</code> 会等一整轮事件循环。它只等微任务，远快于 <code>setTimeout</code>。</li></ul><h3 id="q14-输出顺序题-深挖-await、queuemicrotask、嵌套微任务全混在一起" tabindex="-1"><a class="header-anchor" href="#q14-输出顺序题-深挖-await、queuemicrotask、嵌套微任务全混在一起" aria-hidden="true">#</a> Q14 输出顺序题（深挖）：await、queueMicrotask、嵌套微任务全混在一起</h3><p><strong>考察点</strong>：考微任务队列的&quot;边清空边入队&quot;特性，以及 <code>await</code> 的精确 tick 数。这是本章最难的一题。</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;B&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;C&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;D&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">await</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;E&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">await</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;F&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token function">queueMicrotask</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;G&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;H&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token function">queueMicrotask</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;I&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;J&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>A D J E G H F I B C</code>。第一轮微任务依次是 E、G、H，其中 E 又造出下一个续体、H 又造出 I，新微任务排在队尾。</p></blockquote><ol><li>同步阶段：打印 <code>A</code>；<code>setTimeout</code> 与 IIFE 内的 <code>D</code>；IIFE 遇到 <code>await null</code> 把续体入队（记 m1）；<code>queueMicrotask</code> 入队（m2）；<code>then</code> 回调入队（m3）；最后打印 <code>J</code>。队列为 <code>[m1, m2, m3]</code>。</li><li>清空微任务：m1 打印 <code>E</code> 并让第二个 <code>await</code> 的续体入队（m4，排在队尾）；m2 打印 <code>G</code>；m3 打印 <code>H</code> 并入队 <code>queueMicrotask</code> 的回调（m5）；接着 m4 打印 <code>F</code>；m5 打印 <code>I</code>。可见&quot;队列清了又满&quot;，但始终是先进先出。</li><li>微任务彻底清空后才轮到宏任务：打印 <code>B</code>，其内部再入队一个微任务，本轮宏任务结束后打印 <code>C</code>。</li></ol><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>同步   : A D J
微任务 : [m1,m2,m3] -&gt; E(入队m4) G H(入队m5) F I
宏任务 : B -&gt; 微任务 C
结果   : A D J E G H F I B C
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>await null</code> 要几个微任务 tick？答：现代引擎（Chrome 73+ / Node 12+）是 1 个——<code>await v</code> 内部做 <code>PromiseResolve(v)</code> 再 <code>PerformPromiseThen</code>，<code>v</code> 已是完成态，续体立即入队。</li><li>陷阱：答成 <code>A D J G H E F I B C</code>。m1 是最先入队的，一定要先执行。</li><li>陷阱：以为 <code>H</code> 里的 <code>queueMicrotask</code> 会插到 <code>F</code> 前面。新微任务永远排在队尾，不能插队。</li></ul><h3 id="q15-输出顺序题-深挖-resolve-一个-promise-会多花几个-tick" tabindex="-1"><a class="header-anchor" href="#q15-输出顺序题-深挖-resolve-一个-promise-会多花几个-tick" aria-hidden="true">#</a> Q15 输出顺序题（深挖）：resolve 一个 Promise 会多花几个 tick？</h3><p><strong>考察点</strong>：考 Promise 解析过程（Promise Resolution Procedure）里&quot;thenable 接管&quot;的额外微任务。能说出比普通 resolve 多 tick 就是高手。</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;start&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;executor&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token function">resolve</span><span class="token punctuation">(</span>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;inner&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 注意：resolve 的是一个 Promise</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;then1&#39;</span><span class="token punctuation">,</span> v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;then2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;end&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>start executor end then2 then1 inner</code>。用 thenable 去 resolve 会走&quot;接管&quot;流程，多出至少两个微任务 tick，所以 <code>then2</code> 反而先打印。</p></blockquote><ol><li>同步阶段：打印 <code>start</code>、<code>executor</code>、<code>end</code>。<code>resolve(inner)</code> 发现是 thenable，不会立刻敲定状态，而是入队一个&quot;解析 thenable 任务&quot;（Resolve Thenable Job）。</li><li>队列依次是：<code>[解析任务, then2]</code>。解析任务执行时调用 <code>inner.then(解决外层)</code>，<code>inner</code> 已完成，于是再入队一个任务来真正把外层敲定为 <code>inner</code>。</li><li><code>then2</code> 先打印；随后外层 Promise 完成，触发它注册的反应任务，才打印 <code>then1 inner</code>。整条链比普通 <code>resolve(1)</code> 多了两个 tick。</li></ol><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>同步   : start, executor, end        （此时外层仍 pending）
微任务 : 解析 thenable -&gt; then2 -&gt; 敲定外层 -&gt; then1 inner
结果   : start executor end then2 then1 inner
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>resolve(1)</code> 呢？答：不是 thenable，直接敲定为 fulfilled，只需 1 个 tick 触发 <code>then</code> 回调，输出会变成 <code>then1 1</code> 在 <code>then2</code> 前。</li><li>陷阱：以为 <code>resolve</code> 传 Promise 等价于透传。状态敲定被推迟，这正是 <code>async</code> 函数里 <code>return somePromise</code> 会多绕一圈的原因，也是 <code>return await</code> 曾被认为更慢的由来。</li><li>陷阱：把 <code>Promise.resolve(p)</code> 和 <code>resolve(p)</code> 混为一谈。前者在 <code>p</code> 构造器相同时直接返回 <code>p</code> 本身，不会多 tick。</li></ul><h3 id="q16-promise-有哪三种状态-状态能改回去吗" tabindex="-1"><a class="header-anchor" href="#q16-promise-有哪三种状态-状态能改回去吗" aria-hidden="true">#</a> Q16 Promise 有哪三种状态？状态能改回去吗？</h3><p><strong>考察点</strong>：基础必答。核心是&quot;状态不可逆&quot;和&quot;敲定后不再改变&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>pending</code>（待定）、<code>fulfilled</code>（已兑现）、<code>rejected</code>（已拒绝）三种状态，一旦从 <code>pending</code> 敲定就永久不可逆，后续 <code>resolve/reject</code> 全部忽略。</p></blockquote><ol><li>状态迁移只有两条：<code>pending → fulfilled</code>、<code>pending → rejected</code>。没有回退，也没有 <code>fulfilled → rejected</code>。</li><li>状态敲定后，再调用 <code>resolve</code> 或 <code>reject</code> 不会产生任何效果（静默忽略），这是很多人写错&quot;超时后又被正常结果覆盖&quot;类 bug 的根源。</li><li>同一个 Promise 可以注册多个 <code>then</code>，状态敲定时所有回调按注册顺序进入微任务队列。</li><li>状态只能被内部 <code>resolve/reject</code> 改变，外部拿不到改写能力，这是 Promise 相比纯回调的核心优势。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> p <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve<span class="token punctuation">,</span> reject</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;first&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;second&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 无效</span>
  <span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;third&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 无效</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
p<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// first</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>pending</code> 能一直挂着吗？答：能。没有任何机制会强制敲定它，这就是&quot;永不 resolve 的 Promise&quot;导致内存与逻辑泄漏的原因。</li><li>陷阱：认为 <code>reject</code> 后还能被 <code>then</code> 的第一个参数接住。rejected 只走第二个参数或 <code>catch</code>。</li><li>陷阱：把&quot;状态不可逆&quot;和&quot;值不可变&quot;混为一谈。fulfilled 的值是对象时，对象内容仍可被修改。</li></ul><h3 id="q17-then-的链式调用和值穿透是怎么回事" tabindex="-1"><a class="header-anchor" href="#q17-then-的链式调用和值穿透是怎么回事" aria-hidden="true">#</a> Q17 then 的链式调用和值穿透是怎么回事？</h3><p><strong>考察点</strong>：考 <code>then</code> 的返回值规则。这是 Promise 用得对不对的分水岭。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：每个 <code>then</code> 都返回一个<strong>全新</strong>的 Promise，回调的返回值决定这个新 Promise 的状态；不传回调就原值穿透。</p></blockquote><ol><li>返回值规则：返回普通值 → 新 Promise 变为 fulfilled 并携带该值；返回 Promise 或 thenable → 新 Promise 跟随它的状态（会等待）；抛出异常 → 新 Promise 变为 rejected。</li><li>值穿透：<code>then</code> 的参数不是函数时（<code>null</code>、<code>undefined</code>、非函数）会被替换成恒等函数，值原样往后传，所以链中间可以&quot;跳过&quot;处理。<code>catch</code> 之后继续 <code>then</code> 可以恢复链条，这是错误恢复的常用姿势。</li><li>忘记 <code>return</code> 是最常见的坑：回调里 <code>return</code> 丢了，下一个 <code>then</code> 拿到的是 <code>undefined</code>，而不是内层 Promise 的结果。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span>                 <span class="token comment">// 值穿透</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> v <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">finally</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;finally&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// 不改变值，只做收尾</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 先 finally，再 2</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>finally</code> 会改变值吗？答：不会。它不接收值也不返回值，回调的返回值被忽略，原值继续往下传，唯一例外是 <code>finally</code> 里抛出异常或返回 rejected Promise。</li><li>陷阱：在 <code>then</code> 里写 <code>arr.forEach(async ...)</code> 然后以为链会等它。只有 <code>return</code> 出去的 Promise 才会被等待。</li><li>陷阱：以为 <code>.catch</code> 能捕获它<strong>前面</strong>所有错误却不影响后面。<code>catch</code> 之后链条默认恢复为 fulfilled，除非它自己又抛。</li></ul><h3 id="q18-then-的回调为什么设计成微任务-而不是宏任务" tabindex="-1"><a class="header-anchor" href="#q18-then-的回调为什么设计成微任务-而不是宏任务" aria-hidden="true">#</a> Q18 then 的回调为什么设计成微任务，而不是宏任务？</h3><p><strong>考察点</strong>：考原理与设计动机。能从&quot;规范实现 + 为什么要这样设计&quot;两个角度答就很好。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：规范上 <code>then</code> 注册的反应任务通过&quot;入队一个 Promise 作业&quot;（HostEnqueuePromiseJob）进微任务队列；设计上是为了让本轮状态变更在渲染之前全部收敛。</p></blockquote><ol><li>规范实现路径：<code>then</code> 调用 <code>PerformPromiseThen</code>，状态已敲定时创建一个 Promise 反应任务（PromiseReactionJob），通过宿主钩子入队微任务，因此永远在当前宏任务结束前执行完。</li><li>保证一致性：如果 <code>then</code> 是宏任务，中间会被渲染和其他宏任务插队，用户可能先看到&quot;半更新&quot;的界面。微任务让一整条 <code>then</code> 链在同一次渲染前收敛完毕。</li><li>延迟最低：微任务不需要等下一帧或下一个任务，是&quot;当前这一轮里能拿到的最快时机&quot;，比 <code>setTimeout(fn, 0)</code> 快一个量级。</li><li>时序确定：微任务先进先出、队列清空才退出，因此 Promise 回调的相对顺序稳定可预测，这也是 Vue 的 <code>nextTick</code>、各类状态库选择微任务做批处理的原因。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>queueMicrotask</code> 和 <code>Promise.then</code> 谁先？答：看入队顺序，同一队列先进先出；<code>queueMicrotask</code> 少一次 Promise 包装，开销更小（见 Q42）。</li><li>陷阱：说&quot;微任务优先级比宏任务高&quot;。它们不是同一队列的优先级比较，而是&quot;每轮宏任务结束后必然清空微任务&quot;的调度规则。</li><li>陷阱：以为微任务能中断同步代码。微任务再急也得等调用栈清空。</li></ul><h3 id="q19-promise-resolve-和-promise-reject-有哪些容易踩的细节" tabindex="-1"><a class="header-anchor" href="#q19-promise-resolve-和-promise-reject-有哪些容易踩的细节" aria-hidden="true">#</a> Q19 Promise.resolve 和 Promise.reject 有哪些容易踩的细节？</h3><p><strong>考察点</strong>：考静态方法的边界行为，尤其是&quot;已 resolve 的 Promise 不一定是新对象&quot;和 <code>reject</code> 不展开。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>Promise.resolve</code> 会做 thenable 展开，且参数本身是同类 Promise 时直接原样返回；<code>Promise.reject</code> 从不展开，传什么就把什么当作拒绝原因。</p></blockquote><ol><li><code>Promise.resolve(p)</code>：若 <code>p</code> 是 Promise 且其 <code>constructor</code> 就是 <code>Promise</code>，直接返回 <code>p</code> 本身（引用相等），不会多包一层；否则新建一个 fulfilled Promise，若是 thenable 还要走接管流程。</li><li><code>Promise.resolve(值)</code> 是&quot;把任何值变成 Promise&quot;的标准手段，<code>await 值</code> 内部也依赖它，Promise 的几处关键特性都依赖这里的展开逻辑。</li><li><code>Promise.reject(p)</code>：即使 <code>p</code> 是个 Promise，也不会展开，整个 <code>p</code> 直接作为 rejected 的原因。所以 <code>catch</code> 拿到的可能是个 Promise 对象（见下面的坑）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> p <span class="token operator">=</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span> <span class="token operator">===</span> p<span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// true</span>
Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;e&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// e</span>
<span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">r</span><span class="token punctuation">(</span>Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;x&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 展开后是 &#39;x&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>new Promise(r =&gt; r(thenable))</code> 和 <code>Promise.resolve(thenable)</code> 一样吗？答：语义一样，都会异步展开；区别只在前者一定创建新 Promise。</li><li>陷阱：executor 里同步 <code>throw</code> 会让 Promise 变 rejected；但在 executor 里 <code>setTimeout(() =&gt; { throw e })</code> 抛出的错误<strong>不会</strong>让 Promise rejected，而是变成全局错误（见 Q28）。</li><li>陷阱：<code>Promise.reject(p)</code> 后写 <code>catch(e =&gt; console.log(e))</code> 期望看到值。实际拿到的是 Promise 对象，需要 <code>await e</code> 才能拿到内部值。</li></ul><h3 id="q20-promise-all-的行为边界你了解哪些" tabindex="-1"><a class="header-anchor" href="#q20-promise-all-的行为边界你了解哪些" aria-hidden="true">#</a> Q20 Promise.all 的行为边界你了解哪些？</h3><p><strong>考察点</strong>：考细节而不是概念。空数组、顺序、短路、非 Promise 元素都是常见追问点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：全部 fulfilled 才 fulfilled 并返回<strong>按输入顺序</strong>排列的结果数组，任一个 rejected 就立即 rejected。</p></blockquote><ol><li>并发发起、统一收口：<code>all</code> 只是把多个 Promise 汇总，不会替你限制并发数。传入的 Promise 在传入前就已经开始执行了（见 Q24）。</li><li>结果顺序与完成顺序无关：内部按输入下标写入结果数组，最慢的排最后也不会打乱顺序。</li><li>失败短路：任一 rejected 立即让 <code>all</code> 变 rejected，其余 Promise 的结果被丢弃——但它们<strong>不会停止执行</strong>，该发的请求还是发完了。</li><li>边界：传空数组立即 fulfilled 为 <code>[]</code>；传非 Promise 值会被 <code>Promise.resolve</code> 包一层，所以可以混用普通值。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>r<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [1, 2]</span>
Promise<span class="token punctuation">.</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>r<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                      <span class="token comment">// []</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么拿到&quot;部分成功&quot;的结果？答：用 <code>allSettled</code>，或者把每个任务包一层 <code>.catch(e =&gt; ({ error: e }))</code> 让 <code>all</code> 永远不会 rejected。</li><li>陷阱：以为 <code>all</code> 会限制并发。<code>ids.map(id =&gt; fetch(id))</code> 在 <code>map</code> 结束时就全部发出去了，一次几百个并发会打满浏览器同域连接数（HTTP/1.1 下通常 6 个），后面全在排队。</li><li>陷阱：以为失败后其余请求会被取消。Promise 没有取消能力，要真正取消得用 <code>AbortController</code>（见 Q34）。</li></ul><h3 id="q21-all、race、allsettled、any-有什么区别-分别什么时候用" tabindex="-1"><a class="header-anchor" href="#q21-all、race、allsettled、any-有什么区别-分别什么时候用" aria-hidden="true">#</a> Q21 all、race、allSettled、any 有什么区别，分别什么时候用？</h3><p><strong>考察点</strong>：考四个静态方法的语义差异与选型判断。必须能说清&quot;什么时候用哪个&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>all</code> 要全成功、<code>allSettled</code> 要全部有结果（不管成败）、<code>race</code> 要第一个敲定（成败都算）、<code>any</code> 要第一个成功。</p></blockquote><ol><li><code>Promise.all</code>：全 fulfilled 才成功，返回结果数组；任一 rejected 就短路失败。用于&quot;缺一不可&quot;的组合请求。</li><li><code>Promise.allSettled</code>：等所有 Promise 敲定，返回 <code>[{status, value|reason}]</code>，永不 rejected。用于&quot;能拿到多少算多少&quot;，比如批量上报、批量删除。</li><li><code>Promise.race</code>：第一个敲定的（无论 fulfilled 还是 rejected）决定结果。用于超时控制（和超时 Promise 赛跑）。</li><li><code>Promise.any</code>：第一个 <strong>fulfilled</strong> 的胜出；全部 rejected 才失败并抛出 <code>AggregateError</code>（内含所有原因）。用于多镜像、多 CDN 取最快可用源。</li></ol><table><thead><tr><th>方法</th><th>成功条件</th><th>失败条件</th><th>返回</th><th>典型场景</th></tr></thead><tbody><tr><td><code>all</code></td><td>全部成功</td><td>任一失败</td><td>结果数组</td><td>组合详情页数据</td></tr><tr><td><code>allSettled</code></td><td>全部敲定</td><td>永不失败</td><td>状态对象数组</td><td>批量操作统计</td></tr><tr><td><code>race</code></td><td>首个敲定</td><td>首个敲定即失败</td><td>首个结果</td><td>超时控制</td></tr><tr><td><code>any</code></td><td>首个成功</td><td>全部失败</td><td>首个成功值</td><td>多源容灾</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>allSettled</code> 是哪个版本有的？答：ES2020，Node 12.9 起、现代浏览器均已支持；老环境需要 <code>all</code> + <code>catch</code> 兜底手写。</li><li>陷阱：把 <code>race</code> 和 <code>any</code> 记反。一句话记法：<code>race</code> 比&quot;谁先结束&quot;，<code>any</code> 比&quot;谁先成功&quot;。</li><li>陷阱：<code>any</code> 在全部失败时不会抛第一个错误，而是抛 <code>AggregateError</code>，其 <code>errors</code> 属性才是原因数组。</li></ul><h3 id="q22-promise-all-和-allsettled-在错误处理上到底差在哪" tabindex="-1"><a class="header-anchor" href="#q22-promise-all-和-allsettled-在错误处理上到底差在哪" aria-hidden="true">#</a> Q22 Promise.all 和 allSettled 在错误处理上到底差在哪？</h3><p><strong>考察点</strong>：考错误处理的取舍，这是实战中最常被问到的一层。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>all</code> 是快速失败，一个 reject 就丢掉全部结果；<code>allSettled</code> 是全部兜住，每个失败都变成一个带 <code>reason</code> 的对象，永不 reject。</p></blockquote><ol><li><code>all</code> 的失败是&quot;短路&quot;：第一个 rejected 立刻把结果抛出去，其他任务的结果即使后来成功了也拿不到。适合&quot;一个失败整个流程就没意义&quot;的场景。</li><li><code>allSettled</code> 的结果结构固定：每项要么 <code>{ status: &#39;fulfilled&#39;, value }</code>，要么 <code>{ status: &#39;rejected&#39;, reason }</code>，之后自己过滤统计。</li><li>用 <code>all</code> 也能模拟 <code>allSettled</code>：给每个任务加 <code>.catch(e =&gt; ({ error: e }))</code>，但这就等于人工丢弃了&quot;抛出的语义&quot;，需要自己约定返回结构。</li><li>选择判断：任务之间有强依赖、失败要立刻提示用户 → <code>all</code>；任务是并列的、要汇总成功率和失败明细 → <code>allSettled</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> tasks <span class="token operator">=</span> ids<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">id</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">/api/item/</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>id<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> r<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> settled <span class="token operator">=</span> <span class="token keyword">await</span> Promise<span class="token punctuation">.</span><span class="token function">allSettled</span><span class="token punctuation">(</span>tasks<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> ok <span class="token operator">=</span> settled<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span>status <span class="token operator">===</span> <span class="token string">&#39;fulfilled&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> failed <span class="token operator">=</span> settled<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span>status <span class="token operator">===</span> <span class="token string">&#39;rejected&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span>reason<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>all</code> 短路后其他请求还会继续跑，会不会造成副作用？答：会。已经发出的写请求不会被撤回，所以批量写操作前要考虑幂等或用 <code>AbortController</code> 主动取消。</li><li>陷阱：<code>allSettled</code> 永不 rejected，所以后面写 <code>try/catch</code> 是无效的，真正的错误在返回值里。</li><li>陷阱：用 <code>all</code> 时忘了给每个任务单独兜底，导致&quot;只有一个失败，但整个列表都渲染不出来&quot;。</li></ul><h3 id="q23-手写实现-promise-all-面试高频手写题" tabindex="-1"><a class="header-anchor" href="#q23-手写实现-promise-all-面试高频手写题" aria-hidden="true">#</a> Q23 手写实现 Promise.all（面试高频手写题）</h3><p><strong>考察点</strong>：考对 Promise 构造、闭包计数、顺序保证与边界处理的综合掌握。写不写得出空数组分支和下标写入是分水岭。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用一个计数器记录完成数、用输入下标写入结果以保证顺序，任一项 reject 就整体 reject，计数器到齐就 resolve。</p></blockquote><ol><li>必须用 <code>Promise.resolve(item)</code> 包一层，才能兼容数组里混入的非 Promise 值（包括同步值）。</li><li>结果必须按下标 <code>results[i] = v</code> 写入，不能 <code>push</code>，否则返回顺序会变成完成顺序。</li><li>边界：空数组要立即 resolve 为 <code>[]</code>，否则计数器永远到不了 0 个元素对应的终值。</li><li>错误处理用 <code>then</code> 的第二个参数直接 <code>reject</code>，天然短路；不要用 <code>catch</code>，否则会把后续逻辑也吞掉。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">myAll</span><span class="token punctuation">(</span><span class="token parameter">iterable</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> items <span class="token operator">=</span> Array<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span>iterable<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve<span class="token punctuation">,</span> reject</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>items<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// 边界：空数组</span>
    <span class="token keyword">const</span> results <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span>items<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">let</span> done <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
    items<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">item<span class="token punctuation">,</span> i</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">value</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>         <span class="token comment">// 包一层，兼容同步值</span>
        results<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> value<span class="token punctuation">;</span>                           <span class="token comment">// 按下标写入，保证顺序</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">++</span>done <span class="token operator">===</span> items<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token function">resolve</span><span class="token punctuation">(</span>results<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 全部到齐才 resolve</span>
      <span class="token punctuation">}</span><span class="token punctuation">,</span> reject<span class="token punctuation">)</span><span class="token punctuation">;</span>                                     <span class="token comment">// 任一失败立即短路</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>陷阱：用 <code>results.push(value)</code> 代替下标写入。这样返回的是完成顺序，面试官会立刻用一个&quot;先慢后快&quot;的用例问穿。</li><li>陷阱：忘了 <code>Promise.resolve</code> 包装，导致传入 <code>[1, 2]</code> 时 <code>item.then</code> 直接报错。</li><li>追问：要不要支持 <code>Symbol.iterator</code>？答：加分项。用 <code>Array.from(iterable)</code> 就够了；原生实现接受任意可迭代对象，用 <code>for...of</code> 遍历更严谨。</li></ul><h3 id="q24-手写一个并发控制器-限制最多-n-个请求同时进行" tabindex="-1"><a class="header-anchor" href="#q24-手写一个并发控制器-限制最多-n-个请求同时进行" aria-hidden="true">#</a> Q24 手写一个并发控制器，限制最多 N 个请求同时进行</h3><p><strong>考察点</strong>：本章最实战的手写题。考闭包状态管理、任务领取与槽位补充。能写出&quot;同步领号&quot;是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：开 N 个槽位，每个槽位完成一个任务就立刻领下一个，直到取完；用一个游标保证领取不重复，用一个计数器判断全部完成。</p></blockquote><ol><li>任务要传函数而不是 Promise：如果传的是已经 <code>new</code> 出来的 Promise，请求在调用 <code>limit</code> 前就全部发出去了，限流无从谈起。</li><li>槽位模型：先启动 <code>min(n, 任务数)</code> 个执行器，每个执行器完成后调用 <code>run()</code> 再领一个，天然把并发数稳定在 N。</li><li>领号必须同步执行（<code>cursor++</code> 在调用任务函数之前），否则同一轮里多个执行器会领到同一个下标。</li><li>结果按下标写回，返回顺序与输入一致；任一失败直接 <code>reject</code>，因为此时后续 <code>run()</code> 不再被调用，队列自然停止。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">limit</span><span class="token punctuation">(</span><span class="token parameter">tasks<span class="token punctuation">,</span> n</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>                    <span class="token comment">// tasks: (() =&gt; Promise)[]</span>
  <span class="token keyword">const</span> results <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span>tasks<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> cursor <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> done <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve<span class="token punctuation">,</span> reject</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> <span class="token function-variable function">run</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>cursor <span class="token operator">&gt;=</span> tasks<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span>     <span class="token comment">// 没有待领任务</span>
      <span class="token keyword">const</span> i <span class="token operator">=</span> cursor<span class="token operator">++</span><span class="token punctuation">;</span>                     <span class="token comment">// 先领号，防止并发重复领取</span>
      tasks<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
        results<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> v<span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">++</span>done <span class="token operator">===</span> tasks<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token function">resolve</span><span class="token punctuation">(</span>results<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">else</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                           <span class="token comment">// 空出槽位立刻补位</span>
      <span class="token punctuation">}</span><span class="token punctuation">,</span> reject<span class="token punctuation">)</span><span class="token punctuation">;</span>                             <span class="token comment">// 任一失败即整体失败</span>
    <span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>tasks<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">resolve</span><span class="token punctuation">(</span>results<span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 空数组立即完成</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> k <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> k <span class="token operator">&lt;</span> Math<span class="token punctuation">.</span><span class="token function">min</span><span class="token punctuation">(</span>n<span class="token punctuation">,</span> tasks<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span> k<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 开 N 个槽</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：要&quot;失败继续跑完&quot;怎么办？答：把 <code>reject</code> 换成记录错误并同样 <code>run()</code> 补位，最后统一 resolve，语义等同 <code>allSettled</code>。</li><li>追问：真实项目会手写吗？答：能手写说明理解，实际多用 <code>p-limit</code>、<code>bottleneck</code> 这类库，它们额外支持动态改并发、优先级队列和速率限制。</li><li>陷阱：把 <code>tasks</code> 写成 Promise 数组，此时 <code>Promise.all</code> 已经是全并发，限流器形同虚设。</li><li>陷阱：以为浏览器端限流只影响服务端压力。同域并发连接数（HTTP/1.1 约 6 个）不控制，后续请求全在排队，反而拖慢整体响应。</li></ul><h3 id="q25-async-函数的本质是什么" tabindex="-1"><a class="header-anchor" href="#q25-async-函数的本质是什么" aria-hidden="true">#</a> Q25 async 函数的本质是什么？</h3><p><strong>考察点</strong>：考你是否理解 <code>async</code> 不是语法糖那么简单。能从&quot;返回 Promise / 生成器 + 自动执行器 / 引擎状态机&quot;三个层次答就是满分。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>async</code> 函数本质是&quot;一定返回 Promise 的函数&quot;，语义上等价于生成器（Generator）+ 自动执行器，引擎内部则用挂起/恢复的执行上下文实现，比生成器少一层调度开销。</p></blockquote><ol><li>返回 Promise：调用 <code>async</code> 函数不阻塞，立刻拿到一个 Promise。内部 <code>return v</code> 等价于 <code>resolve(v)</code>，<code>throw e</code> 等价于 <code>reject(e)</code>；没有 <code>return</code> 时兑现为 <code>undefined</code>。</li><li>语义等价生成器 + 执行器：<code>await</code> 相当于 <code>yield</code>，执行器把 yield 出来的值 <code>then</code> 一下再把结果 <code>next</code> 回去。Babel 降级 <code>async/await</code> 走的就是这个思路。</li><li>引擎实现不是生成器：规范用 <code>AsyncFunctionStart</code> + <code>Await</code>，靠挂起（suspend）和恢复（resume）执行上下文来工作，是内建状态机，因此比 <code>Generator</code> 手写执行器更快。</li><li>关键副作用：<code>async</code> 函数内部抛错永远不会同步抛出，一定变成 rejected Promise。所以外面直接 <code>try { f() } catch</code> 是抓不到的，必须 <code>await</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;x&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;抓不到&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>        <span class="token comment">// 不会执行</span>
<span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;这样才抓得到&#39;</span><span class="token punctuation">,</span> e<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>async</code> 函数里 <code>return Promise</code> 和 <code>return await Promise</code> 一样吗？答：不一样，见 Q30。</li><li>陷阱：以为 <code>async</code> 函数会开线程。它还是跑在主线程上，只是把等待变成了挂起。</li><li>陷阱：写成 <code>async function f() {}</code> 就以为返回 undefined。它返回的是 fulfilled 为 <code>undefined</code> 的 Promise。</li></ul><h3 id="q26-await-的暂停与恢复机制是怎么实现的" tabindex="-1"><a class="header-anchor" href="#q26-await-的暂停与恢复机制是怎么实现的" aria-hidden="true">#</a> Q26 await 的暂停与恢复机制是怎么实现的？</h3><p><strong>考察点</strong>：本章原理题的天花板。能讲清&quot;右侧先求值 → 挂起上下文 → 注册续体到微任务 → 恢复&quot;这条链就是深挖级答案。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>await v</code> 先同步求出 <code>v</code>，然后把当前 async 函数的执行上下文挂起、把后续代码作为续体注册成 <code>v</code> 的回调；<code>v</code> 敲定后续体作为<strong>微任务</strong>执行，函数上下文被恢复。</p></blockquote><ol><li>右侧同步求值：<code>await expr</code> 的 <code>expr</code> 是同步计算的，所以 <code>await fn()</code> 里 <code>fn()</code> 会立刻执行到返回 Promise 为止。</li><li>挂起：函数执行上下文从调用栈上摘下并保存现场，主线程不会被阻塞，继续跑同步代码和其他任务。这也是为什么 <code>await</code> 之后同一函数里的代码&quot;看起来没执行&quot;。</li><li>订阅：内部走 <code>PromiseResolve(v)</code> 再 <code>PerformPromiseThen</code>，把续体注册为完成回调。如果 <code>v</code> 已经是 fulfilled，这个反应任务立即入微任务队列，只需 1 个 tick。</li><li>恢复：微任务执行时把执行上下文重新压栈，从 <code>await</code> 处继续；函数最终的 Promise 由第一次 <code>return</code> 或未被捕获的 <code>throw</code> 敲定。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：挂起会丢变量吗？答：不会。整个词法环境与局部变量都随执行上下文保存，恢复后完全一致。</li><li>陷阱：说 <code>await</code> 会开新线程或定时器。它纯粹是微任务调度，<code>await 1</code> 和 <code>setTimeout</code> 完全不是一个量级。</li><li>陷阱：<code>await</code> 只挂起<strong>当前这个</strong> async 函数。它的调用者如果不 await，就继续往下跑了。</li></ul><h3 id="q27-async-await-和-then-的等价改写怎么互转" tabindex="-1"><a class="header-anchor" href="#q27-async-await-和-then-的等价改写怎么互转" aria-hidden="true">#</a> Q27 async/await 和 then 的等价改写怎么互转？</h3><p><strong>考察点</strong>：考你是否真的理解两者是同一机制的两种写法。能用 try/catch 与 catch 的位置对应关系说清楚就是过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>await p</code> 相当于把后续代码放进 <code>p.then(...)</code>；<code>try/catch</code> 相当于把 <code>catch</code> 挂在链尾，位置决定错误从哪一层被恢复。</p></blockquote><ol><li>逐句对应：<code>const v = await p</code> → <code>p.then(v =&gt; ...)</code>；<code>return await p</code> → <code>return p.then(...)</code> 或直接 <code>return p</code>；<code>throw e</code> → <code>Promise.reject(e)</code>。</li><li>顺序对应：多个 <code>await</code> 串起来就是 <code>then</code> 链，每一步都是同一套微任务调度，所以两者的输出顺序一一对应。</li><li><code>try/catch/finally</code> 对应 <code>catch</code> 与 <code>finally</code>，但要注意 <code>catch</code> 挂在哪一段：挂在链中间只能捕获它前面那一段的失败。</li><li>不能直接互转的情况：循环里的 <code>await</code>、带 <code>break/continue</code> 的控制流，用 <code>then</code> 改写会非常别扭，这正是 <code>async/await</code> 的价值所在。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">load</span><span class="token punctuation">(</span><span class="token parameter">url</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token keyword">const</span> r <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token keyword">await</span> r<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
<span class="token comment">// 等价写法</span>
<span class="token keyword">function</span> <span class="token function">load</span><span class="token punctuation">(</span><span class="token parameter">url</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token function">fetch</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> r<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：改写成 <code>then</code> 后错误位置一致吗？答：基本一致，但 <code>return await</code> 与 <code>return</code> 在 <code>try</code> 里的行为不同（见 Q30），改写时要特别留意。</li><li>陷阱：把 <code>.catch(() =&gt; null)</code> 写到链中间，导致后面的 <code>then</code> 依然会执行。等价改写时必须核对恢复点。</li></ul><h3 id="q28-try-catch-捕获不到哪些异步错误" tabindex="-1"><a class="header-anchor" href="#q28-try-catch-捕获不到哪些异步错误" aria-hidden="true">#</a> Q28 try/catch 捕获不到哪些异步错误？</h3><p><strong>考察点</strong>：实战排错题。能列出三类以上具体场景并给出正确做法，就是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>try/catch</code> 只能捕获同步执行栈里的错误；一切在&quot;新的调用栈&quot;里抛出的错误都抓不到，包括定时器回调、事件回调、以及没被 <code>await</code> 的 Promise 拒绝。</p></blockquote><ol><li>定时器与事件回调：<code>setTimeout</code>、<code>setInterval</code>、<code>addEventListener</code> 的回调都在新的宏任务里执行，此时 <code>try</code> 早已退出，抛出的错误成为全局错误。</li><li>未被 <code>await</code> 或 <code>return</code> 的 Promise：<code>Promise.reject(e)</code> 只是产出一个 rejected Promise，同步的 <code>try</code> 对它无效；这正是最常见的&quot;接口报错了但没进 catch&quot;。</li><li>executor 里异步抛错：<code>new Promise(() =&gt; { setTimeout(() =&gt; { throw e }) })</code> 不会让 Promise 变 rejected，错误变成全局错误。</li><li>正确做法：回调内部自己 <code>try/catch</code>；Promise 统一用 <code>await</code> + <code>try/catch</code> 或 <code>.catch()</code>；事件回调交给全局 <code>window.onerror</code>；Promise 交给 <code>unhandledrejection</code> 兜底（见 Q29）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">try</span> <span class="token punctuation">{</span>
  <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;timer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 抓不到</span>
  Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;promise&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>               <span class="token comment">// 抓不到</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;永远不会执行&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>try { await p } catch</code> 为什么能抓到？答：因为 <code>await</code> 把拒绝转换成了当前函数内的 <code>throw</code>，执行栈是连续的，<code>catch</code> 有效。</li><li>陷阱：只在最外层包一个大 <code>try/catch</code> 就以为万事大吉。异步错误的边界必须逐个处理。</li><li>陷阱：用 <code>.then(onFulfilled).then(onFulfilled)</code> 却把 <code>catch</code> 写在最后，误以为能定位到具体是哪个请求失败。要按层加 <code>catch</code> 并带上上下文。</li></ul><h3 id="q29-未处理的-rejected-promise-会导致什么后果" tabindex="-1"><a class="header-anchor" href="#q29-未处理的-rejected-promise-会导致什么后果" aria-hidden="true">#</a> Q29 未处理的 rejected Promise 会导致什么后果？</h3><p><strong>考察点</strong>：考线上稳定性意识。要知道浏览器和 Node 的行为差异，以及兜底手段。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：浏览器只报&quot;未处理的拒绝&quot;并派发 <code>unhandledrejection</code> 事件、控制台打 <code>Uncaught (in promise)</code>，不中断脚本；Node 15 起默认按未捕获异常处理并<strong>退出进程</strong>。</p></blockquote><ol><li>判定时机：一个 rejected Promise 在微任务清空结束时仍没有任何 handler，就触发 <code>unhandledrejection</code>；如果之后又补了 <code>catch</code>，会再触发 <code>rejectionhandled</code>。所以日志里看到它不代表最终没处理，但通常说明代码有问题。</li><li>浏览器影响：页面不会崩，但错误被静默吞掉，接口失败后界面无任何反馈，是最难排查的一类线上问题；如果这个 Promise 是队列的尾巴，整条队列会停摆。</li><li>Node 影响：<code>unhandledRejection</code> 事件；Node 15 起默认等价于未捕获异常，进程直接退出（可用 <code>--unhandled-rejections=warn</code> 降级），这会让服务进程被一个漏写的 <code>catch</code> 干掉。</li><li>兜底：请求层统一 <code>catch</code> 并上报；全局监听 <code>unhandledrejection</code>（浏览器）/ <code>unhandledRejection</code>（Node）做最后一道防线与监控埋点。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;unhandledrejection&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">report</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>reason<span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// 上报监控</span>
  e<span class="token punctuation">.</span><span class="token function">preventDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// 阻止控制台默认的未捕获提示（可选）</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>Promise.reject(e).catch(...)</code> 会不会触发？答：不会，链上有 handler 就不算未处理。</li><li>陷阱：以为浏览器会因此崩溃。是 Node 才会退出进程，浏览器只是报错。</li><li>陷阱：用 <code>e.preventDefault()</code> 把错误吞干净，结果线上永远发现不了问题。兜底监听必须配上报。</li></ul><h3 id="q30-async-函数里-return-await-和-return-有什么区别" tabindex="-1"><a class="header-anchor" href="#q30-async-函数里-return-await-和-return-有什么区别" aria-hidden="true">#</a> Q30 async 函数里 return await 和 return 有什么区别？</h3><p><strong>考察点</strong>：经典细节题。能说清&quot;是否在本函数内等待&quot;以及&quot;错误能否被本层捕获&quot;就是过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>return await p</code> 会在本函数内等待 <code>p</code> 敲定，因此 <code>p</code> 的拒绝能被本层的 <code>try/catch</code> 捕获；<code>return p</code> 只是把 Promise 原样对外透传，本层 <code>catch</code> 捕获不到，<code>finally</code> 会立刻执行。</p></blockquote><ol><li>行为差异：<code>return await p</code> 相当于先 <code>const v = await p</code> 再 <code>return v</code>；<code>return p</code> 是把 <code>p</code> 交给外层 Promise 的解析过程接管，函数自身的 Promise 最终状态与 <code>p</code> 一致——但拒绝是在<strong>调用方</strong>那里体现。</li><li>错误捕获：只有在 <code>try</code> 块里用 <code>return await p</code>，<code>p</code> 的失败才会走进本函数的 <code>catch</code>。这是最实际的选型依据。</li><li>性能：<code>return await</code> 多一次微任务 tick 和一次可能的 Promise 包装；<code>return p</code> 在纯透传场景更省。但差异是微秒级，不要为它牺牲错误处理正确性。</li><li>选型建议：需要在当前函数内处理错误或做清理 → 写 <code>return await</code>；纯粹转发、错误交给上层 → 写 <code>return</code>。（ESLint 的 <code>no-return-await</code> 也默认豁免 <code>try</code> 块。）</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">a</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">await</span> Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;x&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string">&#39;caught:&#39;</span> <span class="token operator">+</span> e<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
<span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">b</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;x&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string">&#39;caught:&#39;</span> <span class="token operator">+</span> e<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
<span class="token function">a</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span>console<span class="token punctuation">.</span>log<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// caught:x</span>
<span class="token function">b</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span>console<span class="token punctuation">.</span>log<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// x</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>b()</code> 的 <code>finally</code> 什么时候执行？答：立即执行，不等 <code>Promise.reject(&#39;x&#39;)</code> 敲定，因为 <code>return p</code> 相当于同步把 <code>p</code> 交给外层。</li><li>陷阱：机械套用&quot;<code>return await</code> 有性能问题所以一律用 <code>return</code>&quot;，结果 <code>catch</code> 静默失效，是最典型的线上事故来源。</li><li>陷阱：以为 <code>return p</code> 会额外包一层 Promise。外层解析 thenable 会多 tick，但不会真的嵌套成一个新对象。</li></ul><h3 id="q31-for-循环里-await-是串行的-怎么改并发" tabindex="-1"><a class="header-anchor" href="#q31-for-循环里-await-是串行的-怎么改并发" aria-hidden="true">#</a> Q31 for 循环里 await 是串行的，怎么改并发？</h3><p><strong>考察点</strong>：实战性能题。能判断&quot;该不该并发&quot;比会写 <code>Promise.all</code> 更重要。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>for...of</code> 里 <code>await</code> 是逐次串行，总耗时等于各次之和；没有顺序依赖时改用 <code>Promise.all(ids.map(...))</code>，有并发上限要求时加限流控制器。</p></blockquote><ol><li>串行代价：循环体内的 <code>await</code> 必须等上一次结束才进入下一轮，10 个 300ms 的请求就是 3 秒。</li><li>改并发：先 <code>map</code> 出 Promise 数组，再交给 <code>Promise.all</code>，总耗时约为最慢的那一个。注意 <code>map</code> 结束时就全部发出了，并发是无限的。</li><li>加限流：任务量大时套 Q24 的 <code>limit(tasks, n)</code>，把并发压在 N，兼顾速度与服务端压力。</li><li>不能并发的情况：下一次请求的参数来自上一次的响应，或存在写入顺序要求（比如递增的乐观锁版本号），这时串行是正确选择，只能优化单次耗时。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 串行：约 3s</span>
<span class="token keyword">const</span> results <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> id <span class="token keyword">of</span> ids<span class="token punctuation">)</span> results<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token keyword">await</span> <span class="token function">get</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 并发：约 0.3s（最慢那个）</span>
<span class="token keyword">const</span> results <span class="token operator">=</span> <span class="token keyword">await</span> Promise<span class="token punctuation">.</span><span class="token function">all</span><span class="token punctuation">(</span>ids<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">id</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">get</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：并发数全开有什么风险？答：浏览器同域连接数有限（HTTP/1.1 约 6），多余请求排队；服务端可能触发限流；内存与取消链路变复杂。</li><li>陷阱：在 <code>for...of</code> 里用 <code>await</code> 却以为已经并发了。可以看 Network 面板的瀑布图确认——并发是同时开始的竖条，串行是阶梯。</li><li>陷阱：<code>forEach</code> 里写 <code>await</code>。<code>forEach</code> 不等待回调返回的 Promise，等于既没串行也没拿到结果。</li></ul><h3 id="q32-await-后面的代码到底什么时候执行" tabindex="-1"><a class="header-anchor" href="#q32-await-后面的代码到底什么时候执行" aria-hidden="true">#</a> Q32 await 后面的代码到底什么时候执行？</h3><p><strong>考察点</strong>：基础但极易被追问。核心是&quot;微任务，不是下一帧也不是下一个宏任务&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>await</code> 之后的代码在当前宏任务的微任务清空阶段执行，比 <code>setTimeout(fn, 0)</code> 早，和 <code>Promise.then</code> 在同一队列里按入队顺序排。</p></blockquote><ol><li>时序定位：<code>await</code> 之前的同步代码立即执行；<code>await</code> 之后的代码作为续体进微任务队列，在当前宏任务结束、栈空之后被清空执行。</li><li>与 <code>setTimeout</code> 的关系：<code>setTimeout(fn, 0)</code> 要等下一个宏任务，所以 <code>await 0</code> 后面的代码一定先于它执行。</li><li>与 <code>then</code> 的关系：同一个队列，谁先入队谁先执行。所以 <code>await</code> 之后打一行日志和 <code>Promise.resolve().then(打日志)</code> 的先后，取决于两者在同步代码里的先后。</li><li>重要推论：<code>await</code> 不会让出到一个新帧，也不会让渲染插进来。所以&quot;<code>await</code> 一下就能让页面先刷新&quot;是错的，要让浏览器渲染必须用 <code>requestAnimationFrame</code> 或 <code>setTimeout</code> 让出宏任务。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;a&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 同步</span>
  <span class="token keyword">await</span> <span class="token number">0</span><span class="token punctuation">;</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;b&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 微任务</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;c&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// 同步：a c b</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：连续多个 <code>await</code> 会不会被 <code>setTimeout</code> 插队？答：会。每个宏任务结束时都会检查微任务，如果这中间有已到期的定时器并轮到了它，续体要等下一轮。但同一轮里多个 <code>await</code> 会连续跑完。</li><li>陷阱：用 <code>await sleep(0)</code> 想触发一次重绘。要重绘请让出宏任务，例如 <code>await new Promise(r =&gt; setTimeout(r, 0))</code> 或 <code>requestAnimationFrame</code>。</li><li>陷阱：以为 <code>await</code> 之后的代码在&quot;新的一帧&quot;里执行。它仍然属于当前这一轮。</li></ul><h3 id="q33-for-await-of-和异步迭代器是什么" tabindex="-1"><a class="header-anchor" href="#q33-for-await-of-和异步迭代器是什么" aria-hidden="true">#</a> Q33 for await...of 和异步迭代器是什么？</h3><p><strong>考察点</strong>：考 ES2018 的异步迭代能力。知道它能读流、知道它仍是串行，就够用。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>for await...of</code> 用来遍历实现了 <code>Symbol.asyncIterator</code> 的对象，迭代器每次 <code>next()</code> 返回 Promise；它天然串行、惰性拉取，适合流式数据源。</p></blockquote><ol><li>协议：对象提供 <code>[Symbol.asyncIterator]()</code>，返回一个带 <code>next()</code> 的迭代器，<code>next()</code> 返回 <code>Promise&lt;{ value, done }&gt;</code>。它也兼容同步可迭代对象，此时会逐个 <code>await</code> 每个值。</li><li>关键特性：下一轮 <code>next()</code> 在上一轮循环体执行完才被调用，所以是串行等待，不会一次性把所有数据拉进来——这正是处理流与分页游标的价值。</li><li>典型用途：Node 可读流 <code>for await (const chunk of stream)</code>、分页接口的游标遍历、SSE 事件流。</li><li>中断与清理：<code>break</code>、<code>return</code> 或抛出异常都会调用迭代器的 <code>return()</code> 方法，可用于关闭连接、释放句柄。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> pager <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">page</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span>
  <span class="token punctuation">[</span>Symbol<span class="token punctuation">.</span>asyncIterator<span class="token punctuation">]</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token keyword">async</span> <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>page <span class="token operator">&gt;=</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">done</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">value</span><span class="token operator">:</span> <span class="token keyword">undefined</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token keyword">const</span> value <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetchPage</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>page<span class="token operator">++</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token punctuation">{</span> value<span class="token punctuation">,</span> <span class="token literal-property property">done</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">for</span> <span class="token keyword">await</span> <span class="token punctuation">(</span><span class="token keyword">const</span> page <span class="token keyword">of</span> pager<span class="token punctuation">)</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>page<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：和 <code>for...of</code> + <code>await</code> 有区别吗？答：语义相近，主要差别在数据源可以是异步的、且支持惰性求值与 <code>return()</code> 清理；普通数组两者等价。</li><li>陷阱：以为 <code>for await</code> 会自动并发。它和 Q31 的串行循环一样慢，要并发得手动 <code>map</code> + <code>Promise.all</code>。</li><li>陷阱：在不需要清理的场景里忘了写迭代器的 <code>return()</code>，用 <code>break</code> 退出时资源不会自动释放。</li></ul><h3 id="q34-怎么用-abortcontroller-取消请求" tabindex="-1"><a class="header-anchor" href="#q34-怎么用-abortcontroller-取消请求" aria-hidden="true">#</a> Q34 怎么用 AbortController 取消请求？</h3><p><strong>考察点</strong>：实战 API 题。能区分&quot;用户取消&quot;和&quot;真错误&quot;，并知道取消不等于中止服务端处理，才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>AbortController</code> 提供一个 <code>signal</code> 给 <code>fetch</code>，调用 <code>controller.abort(reason)</code> 后请求的 Promise 以 <code>AbortError</code> 拒绝，从而实现客户端取消。</p></blockquote><ol><li>基本用法：<code>const c = new AbortController()</code>，把 <code>c.signal</code> 传给 <code>fetch</code>；需要取消时调用 <code>c.abort()</code>，Promise 会以 <code>DOMException</code>（name 为 <code>AbortError</code>）拒绝。</li><li>区分错误类型：取消是正常业务流，<code>catch</code> 里要判断 <code>e.name === &#39;AbortError&#39;</code> 并直接返回，不要弹错误提示、不要上报监控，否则监控里全是假告警。</li><li>自定义原因：<code>abort(reason)</code> 可传任意值（Chrome 93+ 起支持），此时拒绝原因就是该 <code>reason</code>，<code>signal.reason</code> 也能读到，便于区分&quot;用户切换页面取消&quot;和&quot;超时取消&quot;。</li><li>适用与边界：<code>fetch</code>、<code>addEventListener</code>、<code>AbortSignal.timeout()</code> / <code>AbortSignal.any()</code> 都支持；XHR 用 <code>xhr.abort()</code>，axios v0.22 起支持 <code>signal</code>（旧的 <code>CancelToken</code> 已废弃）。取消只让客户端不再等待，服务端通常仍会处理完。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">let</span> controller<span class="token punctuation">;</span>
<span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">search</span><span class="token punctuation">(</span><span class="token parameter">kw</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  controller<span class="token operator">?.</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token string">&#39;新搜索覆盖&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 取消上一次</span>
  controller <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">AbortController</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">/api/s?q=</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>kw<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">signal</span><span class="token operator">:</span> controller<span class="token punctuation">.</span>signal <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：搜索框场景怎么用？答：每次新请求先 <code>abort</code> 上一个，确保只有最后一次请求的结果被渲染，这是防竞态最干净的做法。</li><li>陷阱：取消后仍走 <code>catch</code> 里的错误提示逻辑，用户切个页面就弹&quot;网络错误&quot;。</li><li>陷阱：以为 abort 能撤回已经到达服务端的写请求。写操作要幂等或加上服务端取消机制。</li></ul><h3 id="q35-怎么封装一个带超时的请求" tabindex="-1"><a class="header-anchor" href="#q35-怎么封装一个带超时的请求" aria-hidden="true">#</a> Q35 怎么封装一个带超时的请求？</h3><p><strong>考察点</strong>：实战封装题。要看你是不是只写 <code>Promise.race</code> 而忘了真正取消请求。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：给 <code>fetch</code> 配一个 <code>AbortController</code>，用 <code>setTimeout</code> 到点调用 <code>abort</code>，请求结束时清掉定时器——一个定时器同时完成&quot;超时判定&quot;和&quot;真正取消&quot;。</p></blockquote><ol><li>只做 <code>Promise.race</code> 的缺陷：外层虽然提前 reject 了，原始请求还在跑、还会占连接、还可能触发后续逻辑。所以超时必须配取消。</li><li>现成方案：现代浏览器与 Node 17.3+ 可用 <code>AbortSignal.timeout(ms)</code>，等价于&quot;带超时的 signal&quot;，代码最简；需要组合多个信号时用 <code>AbortSignal.any([...])</code>。</li><li>错误要可区分：超时与业务失败应该是不同错误类型（自定义 <code>TimeoutError</code> 或带 <code>code</code>），否则调用方无法决定要不要重试。</li><li>兜底细节：<code>finally</code> 里必须 <code>clearTimeout</code>，否则定时器残留；超时要走重试策略时，注意区分&quot;可重试的超时&quot;和&quot;用户主动取消&quot;。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">fetchWithTimeout</span><span class="token punctuation">(</span><span class="token parameter">url<span class="token punctuation">,</span> ms<span class="token punctuation">,</span> options <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> c <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">AbortController</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> timer <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> c<span class="token punctuation">.</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;timeout&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> ms<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token function">fetch</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token operator">...</span>options<span class="token punctuation">,</span> <span class="token literal-property property">signal</span><span class="token operator">:</span> c<span class="token punctuation">.</span>signal <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token punctuation">.</span><span class="token function">finally</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">clearTimeout</span><span class="token punctuation">(</span>timer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 成功或失败都要清</span>
<span class="token punctuation">}</span>

<span class="token comment">// 现成写法（推荐）</span>
<span class="token function">fetch</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">signal</span><span class="token operator">:</span> AbortSignal<span class="token punctuation">.</span><span class="token function">timeout</span><span class="token punctuation">(</span><span class="token number">3000</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>Promise.race</code> 版本还有用吗？答：接口层拿不到 signal（如某些 SDK 只返回 Promise）时是唯一选择，但要接受&quot;请求仍在跑&quot;的事实。</li><li>陷阱：忘了 <code>clearTimeout</code>，短时间内大量请求会堆积定时器。</li><li>陷阱：把超时时间设得比服务端的幂等窗口还短，导致请求成功但客户端以为失败并重试，产生重复数据。</li></ul><h3 id="q36-封装一个带重试和退避的异步函数" tabindex="-1"><a class="header-anchor" href="#q36-封装一个带重试和退避的异步函数" aria-hidden="true">#</a> Q36 封装一个带重试和退避的异步函数</h3><p><strong>考察点</strong>：考工程化能力。要点是&quot;只重试该重试的&quot;&quot;退避加抖动&quot;&quot;有上限且可取消&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用 <code>for</code> 循环包 <code>await</code>，捕获错误后按指数退避等待再试，重试次数用尽才抛出最后一次错误。</p></blockquote><ol><li>只重试可恢复错误：网络中断、超时、5xx、限流（429）值得重试；400/401/403/404 这类业务错误重试毫无意义，只会放大问题。</li><li>指数退避 + 抖动：等待时间为 <code>base * 2 ** i</code> 并叠加随机抖动，避免大批客户端在同一时刻重试形成惊群（thundering herd）。</li><li>三重上限：最大次数、单次超时（可复用 Q35）、总耗时上限，缺一个都可能让请求永远挂着。</li><li>可取消：把 <code>AbortSignal</code> 一路传下去，用户离开页面时立刻中止重试循环；同时把&quot;重试耗尽&quot;包装成可识别的错误类型。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">retry</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> <span class="token punctuation">{</span> times <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> base <span class="token operator">=</span> <span class="token number">300</span> <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> lastErr<span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> times<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">await</span> <span class="token function">fn</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      lastErr <span class="token operator">=</span> e<span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>i <span class="token operator">===</span> times <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span>
      <span class="token keyword">const</span> wait <span class="token operator">=</span> base <span class="token operator">*</span> <span class="token number">2</span> <span class="token operator">**</span> i <span class="token operator">*</span> <span class="token punctuation">(</span><span class="token number">0.5</span> <span class="token operator">+</span> Math<span class="token punctuation">.</span><span class="token function">random</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 指数退避 + 抖动</span>
      <span class="token keyword">await</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span>r<span class="token punctuation">,</span> wait<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">throw</span> lastErr<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：写请求能重试吗？答：只有幂等的才能无脑重试，非幂等写操作需要服务端提供幂等键（idempotency key），否则会产生重复下单。</li><li>陷阱：在 <code>catch</code> 里无条件重试，把 401 也重试三次，既没用又拖慢失败反馈。</li><li>陷阱：重试函数里没有 <code>await</code> 等待间隔，变成快速连打，等效于对服务端做压测。</li></ul><h3 id="q37-怎么封装一个串行任务队列" tabindex="-1"><a class="header-anchor" href="#q37-怎么封装一个串行任务队列" aria-hidden="true">#</a> Q37 怎么封装一个串行任务队列？</h3><p><strong>考察点</strong>：考 Promise 组合能力。核心是&quot;维护一个尾巴&quot;，并且能说清为什么 <code>tail</code> 要接 <code>catch</code>。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：维护一个&quot;尾巴 Promise&quot;，每个新任务都挂在尾巴上执行并成为新尾巴，天然串行且不需要数组和索引。</p></blockquote><ol><li>惰性入队：任务必须用函数包起来（<code>() =&gt; doSomething()</code>），如果直接传 Promise，任务在入队前就已经并发执行了。</li><li>尾巴必须吞掉错误再往后传：写成 <code>tail = run.catch(() =&gt; {})</code>。如果直接 <code>tail = run</code>，一旦某个任务失败，后续所有任务都会因为&quot;rejected 穿透&quot;而自动跳过，队列静默停摆。</li><li>返回 <code>run</code> 而不是 <code>tail</code>：调用方需要拿到<strong>本次任务</strong>的真实结果和错误，而不是被吞掉之后的尾巴。</li><li>适用场景：上传队列、顺序写日志/写库、需要严格保序的埋点上报。比&quot;数组 + 游标 + 递归&quot;的写法短得多。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">createQueue</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> tail <span class="token operator">=</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 队列尾巴</span>
  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token function">enqueue</span><span class="token punctuation">(</span><span class="token parameter">task</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> run <span class="token operator">=</span> tail<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">task</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 排在当前尾巴之后</span>
    tail <span class="token operator">=</span> run<span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 关键：失败不阻塞后续任务</span>
    <span class="token keyword">return</span> run<span class="token punctuation">;</span>                            <span class="token comment">// 调用方仍能拿到本次结果/错误</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> enqueue <span class="token operator">=</span> <span class="token function">createQueue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">enqueue</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">save</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">enqueue</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">save</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 一定在 save(1) 之后执行</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：和 Q24 的并发控制器什么关系？答：并发控制器是&quot;最多 N 个同时跑&quot;，串行队列是 N=1 的特例；两者都用&quot;槽位/尾巴 + 补位&quot;的思路。</li><li>陷阱：写成 <code>tail = run</code>，然后线上出现&quot;一次上传失败后整个队列再也不动了&quot;。</li><li>陷阱：队列无限增长没有上限。批量任务要加上背压或丢弃策略，否则内存会持续上涨。</li></ul><h3 id="q38-generator-和异步是什么关系" tabindex="-1"><a class="header-anchor" href="#q38-generator-和异步是什么关系" aria-hidden="true">#</a> Q38 generator 和异步是什么关系？</h3><p><strong>考察点</strong>：考历史脉络。能说清&quot;async/await 就是 generator + 自动执行器内建化&quot;就是过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：生成器（Generator）本身是同步的暂停/恢复机制，配一个自动执行器就能写同步风格的异步代码，<code>async/await</code> 正是把这一模式内建进语言。</p></blockquote><ol><li>生成器不是异步：<code>function*</code> 调用返回迭代器，<code>yield</code> 只是把执行权交回给调用方，需要外部反复 <code>next()</code> 推进，本身不涉及任何调度。</li><li>执行器模式：<code>yield</code> 出一个 Promise，执行器 <code>then</code> 到结果后调用 <code>next(结果)</code> 把值送回去，遇到拒绝就 <code>iterator.throw(err)</code>。<code>co</code> 库、<code>redux-saga</code> 都是这个模式。</li><li>内建化：ES2017 的 <code>async/await</code> 把&quot;生成器 + 执行器&quot;合并成语言特性，不需要第三方 runner，也不用 <code>function*</code>，同时错误传播更自然（<code>throw</code> 能同步映射到 <code>reject</code>）。</li><li>今天的生成器主要用途不再是异步，而是惰性序列、无限序列、复杂状态机，以及 <code>redux-saga</code> 这类需要&quot;可中断、可测试&quot;副作用的场景。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 执行器：异步版的&quot;自动 next&quot;</span>
<span class="token keyword">function</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token parameter">genFn</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> it <span class="token operator">=</span> <span class="token function">genFn</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve<span class="token punctuation">,</span> reject</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> <span class="token function-variable function">step</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">fn</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      <span class="token keyword">let</span> r<span class="token punctuation">;</span> <span class="token keyword">try</span> <span class="token punctuation">{</span> r <span class="token operator">=</span> <span class="token function">fn</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>e<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token function">reject</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
      r<span class="token punctuation">.</span>done <span class="token operator">?</span> <span class="token function">resolve</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span>value<span class="token punctuation">)</span> <span class="token operator">:</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token function">step</span><span class="token punctuation">(</span>it<span class="token punctuation">.</span>next<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">step</span><span class="token punctuation">(</span>it<span class="token punctuation">.</span>throw<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token function">step</span><span class="token punctuation">(</span>it<span class="token punctuation">.</span>next<span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>async/await</code> 是 <code>Promise</code> 的语法糖吗？答：不严谨。它是&quot;Promise + 挂起/恢复&quot;的语言级能力，规范里用 <code>AsyncFunctionStart</code> 实现，不等同于生成器。</li><li>陷阱：说&quot;<code>yield</code> 会阻塞线程&quot;。它只是暂停函数自身，主线程照常运行。</li><li>陷阱：把生成器与迭代器混为一谈。生成器函数返回的对象同时是迭代器也是可迭代对象。</li></ul><h3 id="q39-从回调地狱到-promise-再到-async-await-演进解决了什么" tabindex="-1"><a class="header-anchor" href="#q39-从回调地狱到-promise-再到-async-await-演进解决了什么" aria-hidden="true">#</a> Q39 从回调地狱到 Promise 再到 async/await，演进解决了什么？</h3><p><strong>考察点</strong>：考你有没有理解&quot;为什么要有 Promise&quot;，而不只是会用。说出控制反转（Inversion of Control）是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：回调地狱的问题不只是嵌套丑，而是错误处理分散、无法返回值、无法并行、以及控制权交给了第三方；Promise 用&quot;状态对象&quot;把控制权收回来，<code>async/await</code> 再把写法拉直。</p></blockquote><ol><li>回调地狱的四个真实痛点：嵌套深导致可读性差；错误处理要在每一层重复写；无法 <code>return</code> 结果给上层；多个异步要串并行时只能靠计数器和标志位。</li><li>控制反转问题：回调模式下把函数交给第三方库调用，你无法保证它只调用一次、一定会调用、或以正确时机调用。Promise 的&quot;状态只能敲定一次且不可逆&quot;直接消灭了这类不确定性。</li><li>Promise 带来的能力：链式扁平、错误沿链传播（一个 <code>catch</code> 兜住整条链）、可组合（<code>all</code>/<code>race</code>/<code>allSettled</code>）、值可返回可传递。</li><li><code>async/await</code> 的增益：把 <code>then</code> 链改成同步书写风格，<code>if</code>/<code>for</code>/<code>try</code> 等控制流可以正常使用，调试栈也恢复正常。</li><li>仍然没解决的：取消（要靠 <code>AbortController</code>）、背压与并发上限（要靠限流器）、超时。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 回调地狱</span>
<span class="token function">getUser</span><span class="token punctuation">(</span>id<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">u</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token function">getOrders</span><span class="token punctuation">(</span>u<span class="token punctuation">.</span>id<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">o</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token function">getDetail</span><span class="token punctuation">(</span>o<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>id<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">d</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>d<span class="token punctuation">)</span><span class="token punctuation">,</span> onErr<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span> onErr<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> onErr<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Promise / async</span>
<span class="token keyword">const</span> u <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getUser</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token punctuation">[</span>first<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getOrders</span><span class="token punctuation">(</span>u<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">await</span> <span class="token function">getDetail</span><span class="token punctuation">(</span>first<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>async/await</code> 会不会重新变成另一种&quot;地狱&quot;？答：不会变成嵌套，但会写出&quot;串行的 await 循环&quot;，性能退化（见 Q31）。</li><li>陷阱：认为 Promise 让代码变成多线程。它只是把回调的注册时机提前了，执行仍然是主线程的微任务。</li><li>陷阱：在回调里同时用回调和 Promise 两套错误处理，导致错误被吞或重复上报。</li></ul><h3 id="q40-浏览器和-node-的事件循环有什么区别" tabindex="-1"><a class="header-anchor" href="#q40-浏览器和-node-的事件循环有什么区别" aria-hidden="true">#</a> Q40 浏览器和 Node 的事件循环有什么区别？</h3><p><strong>考察点</strong>：考差异要点，不要求 Node 细节。能说出&quot;阶段 vs 任务队列&quot;和 &quot;nextTick 优先&quot;就够了。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：浏览器是&quot;每轮取一个宏任务&quot;的队列模型，Node 是&quot;一轮走六个阶段&quot;的循环模型；Node 额外有 <code>process.nextTick</code> 和 <code>setImmediate</code>，且 <code>nextTick</code> 优先于 Promise 微任务。</p></blockquote><ol><li>结构差异：浏览器用任务队列（Task Queue）承载宏任务，每轮只取一个；Node 的事件循环分为 timers、pending callbacks、idle/prepare、poll、check、close callbacks 六个阶段，一轮依次走过。</li><li>微任务差异：Node 有两级微任务队列——<code>process.nextTick</code> 队列优先于 Promise 微任务队列，两者在每个阶段切换时以及每个回调执行后都会被清空。浏览器只有一层微任务队列。</li><li>特有 API：<code>setImmediate</code>（check 阶段执行）只有 Node 有；<code>requestAnimationFrame</code>、<code>MutationObserver</code> 只有浏览器有（Node 没有渲染概念）。</li><li>定时器顺序的确定性不同：主模块顶层中 <code>setTimeout(fn, 0)</code> 与 <code>setImmediate(fn)</code> 的先后取决于进程启动耗时（1ms 边界），顺序不确定；但在 IO 回调内部，<code>setImmediate</code> 一定先执行。</li><li>共同点：调用栈 + 微任务清空 + 下一轮任务的骨架是完全一致的，所以 <code>await</code>/<code>then</code> 的相对顺序规则可以迁移。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：面试时要不要背 Node 六个阶段？答：本章只要求记住差异要点，深入阶段行为建议专门准备 Node 运行时部分再背细节。</li><li>陷阱：把浏览器的&quot;宏任务&quot;概念直接套到 Node 上。Node 里更准确的说法是&quot;阶段&quot;，同一阶段会产生多个任务。</li><li>陷阱：认为 <code>setTimeout(fn, 0)</code> 在 Node 里一定比 <code>setImmediate</code> 早。这正是最容易被反问的一点，只有写在 IO 回调里才有确定答案。</li></ul><h3 id="q41-process-nexttick-和-setimmediate-分别是什么定位" tabindex="-1"><a class="header-anchor" href="#q41-process-nexttick-和-setimmediate-分别是什么定位" aria-hidden="true">#</a> Q41 process.nextTick 和 setImmediate 分别是什么定位？</h3><p><strong>考察点</strong>：Node 侧高频追问。核心是&quot;优先级最高的微任务&quot;与&quot;check 阶段的宏任务&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>process.nextTick</code> 不是定时器，而是优先级高于 Promise 的微任务，在当前操作结束后立即执行；<code>setImmediate</code> 是 check 阶段的宏任务，让出给 IO 之后执行。</p></blockquote><ol><li><code>process.nextTick</code>：在当前操作完成后、事件循环继续推进之前执行。它比 Promise 微任务还早，属于&quot;当前这一轮最紧急的收尾&quot;。</li><li><code>setImmediate</code>：在 check 阶段执行，通常排在 poll 阶段（处理 IO）之后，所以它天然让出给 IO。</li><li>典型顺序：在 IO 回调内部，<code>setImmediate</code> 一定先于 <code>setTimeout(fn, 0)</code>；在主模块顶层则不确定（见 Q40）。</li><li>风险：<code>process.nextTick</code> 递归会让事件循环永远进入不了下一阶段，Node 官方文档明确警告会&quot;饿死&quot;IO；Promise 微任务递归同理。<code>setImmediate</code> 递归则不会饿死，因为它至少要过一整轮。</li><li>选择建议：需要&quot;当前操作后立刻执行&quot;用 <code>nextTick</code>；需要&quot;让出 IO 后再执行&quot;用 <code>setImmediate</code>；顺序无所谓时优先 <code>setImmediate</code>，更安全。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;promise&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
process<span class="token punctuation">.</span><span class="token function">nextTick</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;nextTick&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">setImmediate</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;immediate&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 输出：nextTick -&gt; promise -&gt; immediate</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：浏览器里有 <code>nextTick</code> 吗？答：没有。Vue 2 的 <code>Vue.nextTick</code> 是自己实现的（优先微任务，降级到宏任务），只是名字借用了这个概念。</li><li>陷阱：把 <code>process.nextTick</code> 说成宏任务或定时器。它既不进定时器队列，也不经过阶段。</li><li>陷阱：用 <code>nextTick</code> 递归做轮询，进程 CPU 打满且 IO 无响应。</li></ul><h3 id="q42-queuemicrotask-和-promise-then-有什么区别" tabindex="-1"><a class="header-anchor" href="#q42-queuemicrotask-和-promise-then-有什么区别" aria-hidden="true">#</a> Q42 queueMicrotask 和 Promise.then 有什么区别？</h3><p><strong>考察点</strong>：考对微任务队列的细粒度理解。能说出错误处理差异就是高分。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：两者都是往微任务队列丢回调、按入队顺序执行，区别在于 <code>queueMicrotask</code> 不创建 Promise、抛出的错误走全局未捕获异常，而 <code>then</code> 抛出的错误变成 rejected Promise。</p></blockquote><ol><li>语义更纯：<code>queueMicrotask(fn)</code> 只做一件事——把 <code>fn</code> 排进微任务队列，不产生 Promise 对象、没有 <code>then</code> 的包装与值穿透规则。</li><li>错误处理不同：<code>queueMicrotask</code> 回调抛错会被报为未捕获异常（走 <code>window.onerror</code> 一类全局错误处理）；<code>Promise.then</code> 回调抛错会产出一个 rejected Promise，没有 handler 时触发 <code>unhandledrejection</code>。</li><li>性能：<code>queueMicrotask</code> 少一次 Promise 分配，理论上更轻；但在现代引擎里 <code>then</code> 已被高度优化，实际差异很小，不必为此改代码。</li><li>选型：只是&quot;想在当前同步代码后、渲染前执行一段逻辑&quot;且不需要 Promise 语义（比如自定义调度器、状态库批处理）时用 <code>queueMicrotask</code>；需要串联、错误捕获、组合时用 Promise。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token function">queueMicrotask</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;boom&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 全局未捕获异常</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;boom&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// unhandledrejection</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：Vue 3 的 <code>nextTick</code> 用什么实现？答：优先 <code>Promise.then</code>，降级到 <code>MutationObserver</code> 或 <code>setTimeout</code>，本质是&quot;把回调塞进微任务&quot;。</li><li>陷阱：说 <code>queueMicrotask</code> 比 <code>Promise.then</code> 优先。它们同一个队列，严格按入队顺序。</li><li>陷阱：在 <code>queueMicrotask</code> 里抛出错误却只在全局监听 <code>unhandledrejection</code>，导致漏报。</li></ul><h3 id="q43-微任务死循环会发生什么-长任务怎么拆分" tabindex="-1"><a class="header-anchor" href="#q43-微任务死循环会发生什么-长任务怎么拆分" aria-hidden="true">#</a> Q43 微任务死循环会发生什么？长任务怎么拆分？</h3><p><strong>考察点</strong>：考对调度机制的破坏性认知与性能治理手段。能对比&quot;微任务递归 vs 宏任务递归&quot;就很出彩。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：微任务递归会让事件循环永远进不了下一轮，渲染被彻底饿死、页面假死；长任务则要拆成多个宏任务分片让出主线程。</p></blockquote><ol><li>微任务死循环的后果：队列永远清不空，浏览器没有机会进入渲染步骤，页面完全不响应（动画、点击全死）。相比之下宏任务递归（<code>setTimeout</code> 自我调用）每一轮之间还能渲染，只是慢。</li><li>同类风险：Node 里 <code>process.nextTick</code> 递归会饿死 IO；<code>Promise.resolve().then</code> 递归同理。</li><li>长任务判定：单次执行超过 50ms 即被视为长任务（Long Task），会造成明显掉帧；可以用 <code>PerformanceObserver</code> 监听 <code>longtask</code> 定位罪魁祸首。</li><li>拆分手段：把大循环按批处理，每批之间用 <code>setTimeout</code>/<code>requestIdleCallback</code>/<code>scheduler.postTask</code>（Chrome 115+ 起）让出一轮；纯计算放到 Web Worker。</li><li>让出的目的是给浏览器一个完整的&quot;渲染 + 响应交互&quot;机会，所以必须跨到<strong>下一个宏任务</strong>，用 <code>await Promise.resolve()</code> 让出是无效的（微任务还在同一轮）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">chunkedRun</span><span class="token punctuation">(</span><span class="token parameter">items<span class="token punctuation">,</span> work<span class="token punctuation">,</span> chunk <span class="token operator">=</span> <span class="token number">500</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> items<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i <span class="token operator">+=</span> chunk<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    items<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span>i<span class="token punctuation">,</span> i <span class="token operator">+</span> chunk<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span>work<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">await</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">r</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span>r<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 让出一个宏任务，给渲染与交互机会</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>await Promise.resolve()</code> 能让出渲染吗？答：不能。它只是排到微任务队尾，本轮内还会立刻执行，渲染依然被推迟。</li><li>陷阱：用递归 <code>setTimeout(fn, 0)</code> 做大数据渲染，结果反而更慢。分片大小要按 16ms 预算实测调整，不是越小越好。</li><li>陷阱：以为 Web Worker 能解决一切。DOM 操作不能进 Worker，结果还要 <code>postMessage</code> 序列化回主线程，通信本身也有成本。</li></ul><h3 id="q44-页面切到后台后-定时器会被节流吗" tabindex="-1"><a class="header-anchor" href="#q44-页面切到后台后-定时器会被节流吗" aria-hidden="true">#</a> Q44 页面切到后台后，定时器会被节流吗？</h3><p><strong>考察点</strong>：考实际项目的坑。倒计时失准、轮询空转都要靠这个知识点解释。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：会。页面不可见时定时器最快被限制到约 1 秒一次，Chromium 在后台超过 5 分钟后还会进入约 1 分钟一次的密集节流；<code>requestAnimationFrame</code> 则完全暂停。</p></blockquote><ol><li>基础节流：页面进入后台（不可见）时，浏览器把 <code>setTimeout</code>/<code>setInterval</code> 的最小间隔放宽到约 1 秒，避免后台页面空耗 CPU 与电量。</li><li>密集节流：Chromium 从 88 版起，后台页面超过 5 分钟后，嵌套层级大于 5 的定时器链最快约 1 分钟一次（Intensive Throttling）。所以后台轮询可能几分钟才跑一次。</li><li>rAF 完全暂停：没有渲染帧就没有 rAF 回调。用 rAF 驱动的动画和计时在后台会直接停住。</li><li>应对方式：监听 <code>visibilitychange</code> / <code>document.visibilityState</code>，回到前台时重新拉取数据并用绝对时间戳重新对齐倒计时，而不是用计数器累加。</li><li>注意 Worker 里的定时器同样会被节流；WebSocket 的消息推送不受影响（但要处理断连重连）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>document<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;visibilitychange&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>document<span class="token punctuation">.</span>visibilityState <span class="token operator">===</span> <span class="token string">&#39;visible&#39;</span><span class="token punctuation">)</span> <span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 回前台立刻补一次</span>
  <span class="token keyword">else</span> <span class="token function">stopPolling</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                     <span class="token comment">// 后台停止轮询</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：后台的 <code>setInterval</code> 会补跑漏掉的次数吗？答：不会。节流是&quot;跳过&quot;，不是&quot;排进队列&quot;,回到前台也不会集中触发。</li><li>陷阱：用 <code>setInterval</code> 每秒减一实现 60 秒倒计时。切后台再回来，倒计时明显慢了，正确做法是用截止时间戳相减。</li><li>陷阱：用 rAF 计算耗时。后台时它不执行，累计时间会明显偏少。</li></ul><h3 id="q45-为什么有些调度器用-messagechannel-而不是-settimeout" tabindex="-1"><a class="header-anchor" href="#q45-为什么有些调度器用-messagechannel-而不是-settimeout" aria-hidden="true">#</a> Q45 为什么有些调度器用 MessageChannel 而不是 setTimeout？</h3><p><strong>考察点</strong>：考你是否知道&quot;让出主线程&quot;的正确姿势。能提到 React Scheduler 的取舍就是识别度很高的加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>MessageChannel</code> 产生的是没有 4ms 嵌套钳制、也没有后台节流的宏任务，调度粒度比 <code>setTimeout(fn, 0)</code> 细得多，适合做时间切片。</p></blockquote><ol><li>需求：把一个长任务拆成多个宏任务执行，每个分片之间让浏览器渲染与响应交互。</li><li><code>setTimeout(fn, 0)</code> 的问题：嵌套超过 5 层就被钳制到 4ms，一帧（16.7ms）内最多只能跑几次，分片粒度太粗；页面进后台还会被节流到 1 秒以上（见 Q44）。</li><li><code>MessageChannel</code> 的优势：<code>port.postMessage</code> 投递的是一个普通宏任务，不受 4ms 嵌套钳制，也不受后台定时器节流，因此能在一帧内更密集地穿插执行分片。</li><li>实践印证：React 18 的 Scheduler 就用 <code>MessageChannel</code> 实现时间切片；早期版本曾用 <code>requestIdleCallback</code>，因触发不稳定、只有 50ms 空闲上限且 Safari 不支持而放弃。</li><li>新方向：<code>scheduler.postTask()</code>（Chrome 115+ 起）提供带优先级的原生任务调度，是更标准的方案，但兼容性有限，仍要降级到 <code>MessageChannel</code>。</li><li>使用细节：<code>MessageChannel</code> 的 port 要复用一个实例并调用 <code>port.start()</code>，每次调度都新建 channel 会造成额外开销。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> channel <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MessageChannel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">yieldToMain</span><span class="token punctuation">(</span><span class="token parameter">cb</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  channel<span class="token punctuation">.</span>port1<span class="token punctuation">.</span><span class="token function-variable function">onmessage</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">cb</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  channel<span class="token punctuation">.</span>port2<span class="token punctuation">.</span><span class="token function">postMessage</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 投递一个宏任务，让出主线程</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那为什么不用 <code>requestIdleCallback</code>？答：它在没有空闲时段时会被无限推迟，时机不可预期；时间切片需要&quot;每帧都能拿到一小段时间&quot;，而不是&quot;有空才给&quot;。</li><li>陷阱：认为 <code>MessageChannel</code> 是微任务。它是标准的宏任务，只不过没有定时器的那些限制。</li><li>陷阱：在 <code>yieldToMain</code> 里反复 <code>new MessageChannel()</code>，高频调度下会持续产生垃圾回收压力。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>每轮事件循环固定是：取一个宏任务执行到调用栈清空 → 彻底清空微任务队列 → 需要则执行渲染（含 <code>requestAnimationFrame</code>）→ 再取下一个宏任务。</li><li>同步代码永远最先，微任务永远早于下一个宏任务；<code>await</code> 之后的代码就是微任务，和 <code>Promise.then</code> 同队列、按入队顺序执行。</li><li><code>setTimeout</code> 的延迟是下界不是上界，嵌套超过 5 层按 4ms 钳制；关键定时与倒计时要用绝对时间戳校正，不要依赖 <code>setInterval</code> 的累计次数。</li><li><code>Promise</code> 状态一敲定即不可逆，<code>then</code> 返回新 Promise，回调返回值决定新状态，不传回调则值穿透；<code>then</code> 的回调必须是微任务，才能保证一轮内状态收敛完再渲染。</li><li><code>all</code> 全成功、<code>allSettled</code> 全兜住、<code>race</code> 比谁先结束、<code>any</code> 比谁先成功；限流控制器的关键是把任务写成惰性函数并同步领号。</li><li><code>async</code> 函数一定返回 Promise 且内部抛错只会变成 reject；<code>try/catch</code> 抓不到定时器回调、事件回调和未 <code>await</code> 的 Promise 拒绝。</li><li>需要在函数内捕获错误就用 <code>return await</code>，纯透传才用 <code>return</code>；循环里的 <code>await</code> 是串行，无依赖时应改成 <code>Promise.all</code> 或加限流。</li><li>取消用 <code>AbortController</code>、超时用 <code>AbortSignal.timeout</code> 并清定时器；长任务要拆成分片跨宏任务让出，微任务递归会让页面直接假死。</li></ul>`,364);function c(l,i){return s(),a("div",null,[p,t(" COUNT: 45 ")])}const r=n(e,[["render",c],["__file","03-js-async-eventloop.html.vue"]]);export{r as default};
